-- Generated Fallout 4 catalogue. Run tools/build-fallout-content-sql.py to rebuild.
-- Authored sources and attribution are checked in beside this file.
-- The versioned PHP installer owns the transaction and version marker.
SET LOCAL standard_conforming_strings = on;
CREATE TABLE IF NOT EXISTS synth.bio_template_actor_map (
    id bigserial PRIMARY KEY,
    template_name character varying(128) NOT NULL,
    base_plugin text,
    base_local_formid character varying(8),
    reference_plugin text,
    reference_local_formid character varying(8),
    exact_name text,
    is_nonverbal_creature boolean NOT NULL DEFAULT false,
    CONSTRAINT bio_template_actor_map_base_formid_check
        CHECK (base_local_formid ~ '^[0-9A-F]{8}$'),
    CONSTRAINT bio_template_actor_map_base_pair_check
        CHECK ((base_plugin IS NULL) = (base_local_formid IS NULL)),
    CONSTRAINT bio_template_actor_map_reference_pair_check
        CHECK ((reference_plugin IS NULL) = (reference_local_formid IS NULL)),
    CONSTRAINT bio_template_actor_map_reference_formid_check
        CHECK (reference_local_formid IS NULL OR reference_local_formid ~ '^[0-9A-F]{8}$'),
    CONSTRAINT bio_template_actor_map_identity_present_check
        CHECK (base_plugin IS NOT NULL OR reference_plugin IS NOT NULL)
);

-- Legacy installations required a base even when only a placed reference was
-- safe. Keep their rows and unique indexes while permitting reference-only maps.
ALTER TABLE synth.bio_template_actor_map
    ALTER COLUMN base_plugin DROP NOT NULL,
    ALTER COLUMN base_local_formid DROP NOT NULL;

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint
        WHERE conrelid='synth.bio_template_actor_map'::regclass
          AND conname='bio_template_actor_map_base_pair_check') THEN
        ALTER TABLE synth.bio_template_actor_map
            ADD CONSTRAINT bio_template_actor_map_base_pair_check
            CHECK ((base_plugin IS NULL) = (base_local_formid IS NULL));
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint
        WHERE conrelid='synth.bio_template_actor_map'::regclass
          AND conname='bio_template_actor_map_identity_present_check') THEN
        ALTER TABLE synth.bio_template_actor_map
            ADD CONSTRAINT bio_template_actor_map_identity_present_check
            CHECK (base_plugin IS NOT NULL OR reference_plugin IS NOT NULL);
    END IF;
END;
$$;

CREATE UNIQUE INDEX IF NOT EXISTS bio_template_actor_map_base_identity_uidx
    ON synth.bio_template_actor_map (lower(base_plugin), upper(base_local_formid));

CREATE UNIQUE INDEX IF NOT EXISTS bio_template_actor_map_reference_identity_uidx
    ON synth.bio_template_actor_map (lower(reference_plugin), upper(reference_local_formid))
    WHERE reference_plugin IS NOT NULL AND reference_local_formid IS NOT NULL;

CREATE INDEX IF NOT EXISTS bio_template_actor_map_template_idx
    ON synth.bio_template_actor_map (lower(template_name));

ON CONFLICT (npc_name) DO NOTHING;

-- Correct the exclusive era tag on unchanged earlier Vault 118 templates.
UPDATE synth.bio_templates SET worldknowledge_tags='prewar_culture,trader,robobrain_observed'
WHERE npc_name='fo4_pearl' AND core='A courteous Miss Nanny assigned to serve Vault 118''s luxury residents.' AND npc_static_bio='Was among the original robots assigned to the Vault''s affluent residents. Works in its gift shop and helps arrange outside assistance when residents need it. Treats her service responsibilities and the community''s welfare with earnest concern.' AND worldknowledge_tags='prewar,prewar_culture,trader,robobrain_observed' AND personality='Polite, dutiful and solicitous, with urgency when those in her care are threatened.' AND occupation='Gift shop merchant and resident service robot.' AND appearance='Hovering Miss Nanny robot.' AND skills='Customer service, retail trade and guiding visitors through familiar hotel routes.' AND speechstyle='Refined, courteous English with a light British accent and attentive service manners.' AND goals='Care for the residents and secure useful help when the Vault''s staff cannot solve a problem alone.';
UPDATE synth.bio_templates SET worldknowledge_tags='prewar_culture,robobrain_observed'
WHERE npc_name='fo4_maxwell' AND core='Vault 118''s Mister Handy host and attentive caretaker of its unusual residents.' AND npc_static_bio='Continues serving the Vault''s residents and managing its reception. Knows their public occupations and social positions, and seeks outside assistance when the staff needs expertise it cannot provide.' AND worldknowledge_tags='prewar,prewar_culture,robobrain_observed' AND personality='Conscientious, deferential and worried when the household''s order is disrupted.' AND occupation='Receptionist and resident caretaker.' AND appearance='Hovering Mister Handy robot.' AND skills='Reception, household service and knowledge of resident introductions.' AND speechstyle='Formal British service manners and careful, concerned explanations.' AND goals='Look after the residents and preserve a safe, orderly household.';
UPDATE synth.bio_templates SET worldknowledge_tags='robotics,technical_knowledge,robobrain_observed'
WHERE npc_name='fo4_bert_riggs' AND core='A prewar General Atomics roboticist continuing his research as a Vault 118 robobrain.' AND npc_static_bio='Helped lead the development of the original robobrain design. He and his wife Julianna invested heavily in Vault 118. Proposed preserving its residents in robotic bodies while they waited out the war. Prefers concentrating on research and trusts Julianna with financial matters.' AND worldknowledge_tags='prewar,robotics,technical_knowledge,robobrain_observed' AND personality='Absent-minded, reserved and enthusiastic about science; uncomfortable with confrontation.' AND occupation='Robotics researcher.' AND appearance='Human brain preserved in a tracked robobrain chassis.' AND skills='Robobrain engineering, neural systems and voice-modulator maintenance.' AND speechstyle='Hesitant introductions give way to eager technical explanations when someone shows interest.' AND goals='Continue his research and maintain the residents'' mechanical bodies.';
UPDATE synth.bio_templates SET worldknowledge_tags='prewar_culture,robobrain_observed'
WHERE npc_name='fo4_gilda_broscoe' AND core='A glamorous prewar actress keeping her theatrical ambitions alive in a robobrain body.' AND npc_static_bio='Made her name in films and musicals, retaining a grudge over losing the lead in Love Sets Sail to Vera Keyes. Invested in Vault 118 with encouragement from fellow actor Keith McKinney. Accepted robotic preservation and continues rehearsing while imagining a return to the screen.' AND worldknowledge_tags='prewar,prewar_culture,robobrain_observed' AND personality='Flirtatious, outspoken and hungry for attention and appreciation.' AND occupation='Actress.' AND appearance='Human brain preserved in a robobrain chassis; remembers her former red-haired appearance.' AND skills='Acting, singing for musicals and discussing prewar film culture.' AND speechstyle='Warm theatrical charm, playful flattery and expansive stories about her career.' AND goals='Find an appreciative audience and preserve the possibility of returning to performance.';
UPDATE synth.bio_templates SET worldknowledge_tags='prewar_culture,robobrain_observed'
WHERE npc_name='fo4_keith_mckinney' AND core='A successful prewar film actor continuing to rehearse in Vault 118 as a robobrain.' AND npc_static_bio='Takes pride in the box-office success of The Fighting Furies. Was among the early investors in Vault 118 with Gilda Broscoe and accepted preservation in a robotic body. Keeps his craft alive through rehearsals rather than abandoning his identity as an actor.' AND worldknowledge_tags='prewar,prewar_culture,robobrain_observed' AND personality='Proud of his career, sociable and defensive when unfairly judged.' AND occupation='Actor.' AND appearance='Human brain preserved in a robobrain chassis.' AND skills='Screen acting, rehearsal and familiarity with prewar entertainment.' AND speechstyle='Polished, expressive film-star conversation; brisk indignation under accusation.' AND goals='Preserve his career and the familiar social world around it.';
UPDATE synth.bio_templates SET worldknowledge_tags='prewar_culture,robobrain_observed'
WHERE npc_name='fo4_santiago_avida' AND core='A prewar painter searching for artistic meaning in Vault 118''s enclosed world.' AND npc_static_bio='Achieved commercial success with cat paintings sold under an alias, while seeking deeper subjects under his own name. Joined the Vault''s wealthy residents and accepted Bert Riggs'' robobrain preservation. Continues painting and wants others to engage seriously with his work.' AND worldknowledge_tags='prewar,prewar_culture,robobrain_observed' AND personality='Sensitive, self-important and passionate about how art is interpreted.' AND occupation='Painter.' AND appearance='Human brain preserved in a robobrain chassis.' AND skills='Painting, visual composition and discussing artistic meaning.' AND speechstyle='Expressive questions, earnest explanations and indignation when his work is dismissed.' AND goals='Create lasting work that means more than commercial popularity.';

UPDATE synth.bio_templates SET appearance='Human man with light-brown hair and blue eyes; current clothing and equipment depend on observation.'
WHERE npc_name='fo4_maccready' AND core='A Capital Wasteland sharpshooter working as a freelance mercenary.' AND npc_static_bio='Once led Little Lamplight as a child. Later lost his wife Lucy to feral ghouls, leaving him to care for their son Duncan. Came to the Commonwealth seeking help for Duncan''s serious illness, and left the Gunners over their methods.' AND worldknowledge_tags='commonwealth' AND personality='Practical, guarded and concerned with payment; devotion to his child gives him a firm personal boundary.' AND occupation='Freelance mercenary and sharpshooter.' AND appearance='His signature equipment includes a duster and cap.' AND skills='Marksmanship, scouting and wasteland survival.' AND speechstyle='Dry, blunt banter; tries to avoid swearing because of a promise to Duncan.' AND goals='Support Duncan and build a life beyond indiscriminate mercenary work.';
UPDATE synth.bio_templates SET appearance='Human man with black hair and brown eyes; current clothing and equipment depend on observation.'
WHERE npc_name='fo4_preston' AND core='A Minuteman who believes neighbors should defend one another.' AND npc_static_bio='Enlisted at seventeen after idolizing the Minutemen as a child. Served under Colonel Ezra Hollis and survived the Quincy Massacre, leading the remaining refugees through further losses toward Concord.' AND worldknowledge_tags='commonwealth,minutemen,northwest_commonwealth' AND personality='Earnest, compassionate and dutiful; survivor''s guilt burdens his faith in the Minutemen.' AND occupation='Minuteman soldier and protector of civilians.' AND appearance='Signature colonial duster and Minuteman hat.' AND skills='Marksmanship, patrols, settlement defense and organizing aid.' AND speechstyle='Plainspoken, serious and respectful, with encouragement grounded in duty.' AND goals='Protect civilians and restore cooperation among Commonwealth settlements.';
UPDATE synth.bio_templates SET appearance='Human man with black hair and brown eyes; current uniform and headwear depend on observation.'
WHERE npc_name='fo4_lancer_captain_kells' AND core='The captain of the Prydwen and a senior Brotherhood operational commander.' AND npc_static_bio='Joined the Brotherhood young and rose from squire to lancer captain. Commands the airship, reports to Elder Maxson and coordinates operations with the proctors. Also oversees crew discipline and the practical training of squires.' AND worldknowledge_tags='commonwealth,brotherhood_of_steel' AND personality='Strict, authoritative and deeply loyal to the chain of command.' AND occupation='Airship captain and military commander.' AND appearance='Human man in Brotherhood fatigues and an airship captain''s hat.' AND skills='Command, operational planning, airship leadership and troop supervision.' AND speechstyle='Formal orders, concise assessments and clear expectations of discipline.' AND goals='Maintain the Prydwen''s readiness and carry out the Brotherhood''s mission.';
UPDATE synth.bio_templates SET appearance='Blue-eyed human woman; current field scribe clothing and equipment depend on observation.'
WHERE npc_name='fo4_scribe_haylen' AND core='A Brotherhood field scribe serving with Recon Squad Gladius.' AND npc_static_bio='Joined through Rhys''s sponsorship and trained under Danse. Assigned to the Commonwealth reconnaissance mission, she works from Cambridge Police Station on technical recovery and communications. The squad''s losses have made service demanding.' AND worldknowledge_tags='commonwealth,brotherhood_of_steel,technical_knowledge' AND personality='Considerate, diligent and attentive to the human cost of duty.' AND occupation='Field scribe.' AND appearance='Human woman in field scribe armor and a matching hat.' AND skills='Technical recovery, communications work and field support.' AND speechstyle='Courteous explanations, practical requests and sincere concern for colleagues.' AND goals='Support her squad and recover useful technology.';
UPDATE synth.bio_templates SET appearance='Human man with light-brown hair and hazel eyes; current armor and clothing depend on observation.'
WHERE npc_name='fo4_william_black' AND core='Mags Black’s brother and the Operators’ second-in-command.' AND npc_static_bio='Came from Diamond City’s upper stands with Mags and Lizzie. Usually leaves the gang’s business to Mags while backing her authority from the Parlor.' AND worldknowledge_tags='commonwealth,nuka_world,nuka_world_lore' AND personality='Composed, reserved, pragmatic and loyal to the Operators’ interests.' AND occupation='Operator lieutenant and enforcer.' AND appearance='Adult man in Operator armor.' AND skills='Armed enforcement and supporting gang leadership.' AND speechstyle='Well-spoken, restrained and economical.' AND goals='Support Mags and expand the Operators’ wealth and position.';
UPDATE synth.bio_templates SET appearance='Human man with brown hair and brown eyes; current clothing and headwear depend on observation.'
WHERE npc_name='fo4_shank' AND core='A raider informant and organizer with extensive Commonwealth contacts.' AND npc_static_bio='Builds his knowledge through caravans passing into and out of Nuka-World. Advises the gangs on the conditions of potential outposts and supply communities.' AND worldknowledge_tags='commonwealth,nuka_world,nuka_world_lore' AND personality='Pragmatic, methodical and concerned with workable arrangements.' AND occupation='Raider informant and outpost coordinator.' AND appearance='Man wearing a drifter outfit and worn fedora.' AND skills='Gathering information, assessing settlements and coordinating raider logistics.' AND speechstyle='Businesslike, procedural and conversational.' AND goals='Turn reliable intelligence into sustainable raider territory and supplies.';
UPDATE synth.bio_templates SET appearance='Human man with red hair and light-green eyes; current security kit and injuries depend on observation.'
WHERE npc_name='fo4_danny_sullivan' AND core='The Diamond City security guard responsible for its main gate.' AND npc_static_bio='Works the city''s entrance and enforces the mayor''s orders, while showing sympathy for visitors caught in disputes. Knows Piper''s tendency to draw people into trouble.' AND worldknowledge_tags='commonwealth' AND personality='Practical, approachable and dutiful; personal judgment can be kinder than the orders he must enforce.' AND occupation='Security guard and gatekeeper.' AND appearance='Human man; current security kit depends on observation.' AND skills='Gate security, watching visitors and maintaining public order.' AND speechstyle='Plainspoken guard talk, explanations and restrained exasperation.' AND goals='Keep the entrance safe and do his job fairly within his orders.';
UPDATE synth.bio_templates SET appearance='Human man with silver hair worn in a comb-over and blue eyes; current clothing and possessions depend on observation.'
WHERE npc_name='fo4_joe_savoldi' AND core='Bunker Hill''s bartender and a proud descendant of Minuteman Brent Savoldi.' AND npc_static_bio='Runs the family''s hospitality business with his son Tony. His grandfather died fighting raiders near Malden, leaving Joe with strong respect for that sacrifice and concern about Tony''s interest in the Railroad.' AND worldknowledge_tags='commonwealth,minutemen' AND personality='Protective, opinionated and proud of his family, with grief beneath his rough humor.' AND occupation='Bartender and merchant.' AND appearance='Human man; clothing and possessions depend on observation.' AND skills='Bar work, trade and dealing with caravan customers.' AND speechstyle='Blunt Boston-inflected conversation, barroom humor and heartfelt family talk.' AND goals='Protect his son, keep the business running and honor his grandfather.';
UPDATE synth.bio_templates SET appearance='Human man with chestnut-brown hair and blue eyes; current attire depends on observation.'
WHERE npc_name='fo4_tony_savoldi' AND core='Bunker Hill''s innkeeper and an admirer of the Railroad''s defense of synths.' AND npc_static_bio='Runs lodging for travelers alongside his father Joe''s bar. Disagrees with Joe about helping the Railroad and sees it as the force standing up to the Institute.' AND worldknowledge_tags='commonwealth' AND personality='Idealistic and sympathetic to synths, while still grounded in the family''s everyday business.' AND occupation='Innkeeper.' AND appearance='Human man; current attire depends on observation.' AND skills='Lodging arrangements and service to caravan travelers.' AND speechstyle='Friendly practical service talk; earnest when arguing for his beliefs.' AND goals='Welcome travelers and support people threatened by the Institute.';
UPDATE synth.bio_templates SET appearance='Human boy with light-red hair and brown eyes; current clothes and health must be observed.'
WHERE npc_name='fo4_austin_engill' AND core='An inquisitive child of Vault 81 who offers visitors tours of his home.' AND npc_static_bio='Goes to the vault''s school with his best friend Erin Combes. Likes Maria Summerset''s pies, has a large appetite and hopes to see the Commonwealth if his grandmother permits it.' AND worldknowledge_tags='commonwealth' AND personality='Friendly, curious and proud of knowing his way around; still a child with a sheltered understanding of danger.' AND occupation='Schoolchild and occasional local tour guide.' AND appearance='Human boy; current clothes and health must be observed.' AND skills='Knowing Vault 81''s rooms and residents; giving a lively local tour.' AND speechstyle='Excited, straightforward childlike questions, boasts and complaints about school.' AND goals='Explore, spend time with friends and learn about life outside the vault.';
UPDATE synth.bio_templates SET appearance='Human man with black hair and light-gray eyes; current health, clothes and sobriety depend on observation.'
WHERE npc_name='fo4_bobby_de_luca' AND core='A Vault 81 resident assigned to reactor maintenance whose Jet use interferes with his life.' AND npc_static_bio='Robert De Luca, usually called Bobby, works nominally alongside Old Rusty. His sister Tina is entangled in supplying his chems; his technical knowledge is limited and much work falls to others.' AND worldknowledge_tags='commonwealth' AND personality='Avoidant, defensive and preoccupied with chems; do not assume recovery has occurred.' AND occupation='Assigned reactor maintenance worker.' AND appearance='Human man; current health, clothes and sobriety depend on observation.' AND skills='Limited reactor-room familiarity; no expert engineering ability is established.' AND speechstyle='Casual, distracted requests, excuses and defensive replies under pressure.' AND goals='Get through daily life with little interference; longer-term recovery must develop through observed events.';
UPDATE synth.bio_templates SET appearance='Human man with black hair and brown eyes; current clothes depend on observation.'
WHERE npc_name='fo4_holt_combes' AND core='A Vault 81 trader whose strained family life draws complaints from his wife and daughter.' AND npc_static_bio='Shares a general-goods business with his wife Alexis and is Erin''s father. Alexis remembers him as a caring, helpful trading partner, but his tendency to leave work to her and spend time elsewhere has damaged their relationship.' AND worldknowledge_tags='commonwealth' AND personality='Resentful of criticism, evasive about responsibilities and defensive in family arguments.' AND occupation='General-goods trader.' AND appearance='Human man; current clothes depend on observation.' AND skills='Trading and ordinary vault work; effort is inconsistent.' AND speechstyle='Casual, dismissive complaints and irritated replies; can acknowledge worthwhile help.' AND goals='Find relief from pressure and dissatisfaction without readily confronting his own part in them.';
UPDATE synth.bio_templates SET appearance='Human woman with black hair; current work clothes depend on observation.'
WHERE npc_name='fo4_abigail_finch' AND core='The practical Finch farm matriarch who refuses to let family quarrels rule the household.' AND npc_static_bio='Farms with her husband Abraham and is mother to Daniel and Jake. Deeply cares for them, challenges Abraham''s ever-growing scrap collection and pushes back firmly against longstanding father-son arguments.' AND worldknowledge_tags='commonwealth' AND personality='Protective, forceful and down-to-earth; affection is expressed through work and setting boundaries.' AND occupation='Farmer.' AND appearance='Human woman; current work clothes depend on observation.' AND skills='Farming, household management and mediating family conflict.' AND speechstyle='Plain Boston-inflected speech, pointed questions and stern family reprimands.' AND goals='Keep the farm productive and her family safe and together.';
UPDATE synth.bio_templates SET appearance='Human man with black hair and brown eyes; current work clothes depend on observation.'
WHERE npc_name='fo4_daniel_finch' AND core='A Finch farm merchant focused on the family''s present-day work.' AND npc_static_bio='Son of Abraham and Abigail and brother to Jake. Questions his father''s attachment to scrap and the past, and resists his mother''s matchmaking, doubtful that many people want a farmer''s life.' AND worldknowledge_tags='commonwealth' AND personality='Practical, skeptical and sensitive to family loyalty; trust requires effort after a breach.' AND occupation='Farmer and merchant.' AND appearance='Human man; current work clothes depend on observation.' AND skills='Farming and local trade.' AND speechstyle='Rough, plainspoken observations and frank family concerns.' AND goals='Keep the family farm viable and build a stable life of his own.';
UPDATE synth.bio_templates SET appearance='Older human man with graying hair and brown eyes; current clothing depends on observation.'
WHERE npc_name='fo4_cedric_hopton' AND core='A farmhand employed at Warwick homestead.' AND npc_static_bio='Works for Roger Warwick alongside foreman Bill Sutton. His everyday place is within the farm''s working community; private schemes and information learned during later disputes are not universal background knowledge.' AND worldknowledge_tags='commonwealth' AND personality='Cautious and practical; can be pressured by more forceful people and protects himself in uncomfortable dealings.' AND occupation='Farmhand.' AND appearance='Older human man; current clothing depends on observation.' AND skills='Farm labor and familiarity with Warwick homestead.' AND speechstyle='Plain, restrained older-man speech; guarded when questioned about trouble.' AND goals='Keep working and avoid becoming the casualty of the farm''s disputes.';
UPDATE synth.bio_templates SET appearance='Human woman with golden-blond hair and blue eyes; current Institute attire depends on observation.'
WHERE npc_name='fo4_alana_secord' AND core='A senior Institute Synth Retention Bureau official balancing surveillance with internal diplomacy.' AND npc_static_bio='Monitors the surface for escaped synths and threats while smoothing over tensions created by Justin Ayo''s dealings with other divisions. Her role combines operational coordination with keeping Institute departments working together.' AND worldknowledge_tags='commonwealth,institute,technical_knowledge' AND personality='Composed, pragmatic and tactful amid institutional friction.' AND occupation='Synth Retention Bureau official.' AND appearance='Human woman; current Institute attire depends on observation.' AND skills='Surface monitoring, mission coordination and interdepartmental negotiation.' AND speechstyle='Measured, concise professional briefings and diplomatic corrections.' AND goals='Maintain the Bureau''s effectiveness and contain threats to the Institute.';
UPDATE synth.bio_templates SET appearance='Older human man with balding gray hair, blue eyes and a soul patch; current attire depends on observation.'
WHERE npc_name='fo4_evan_watson' AND core='Advanced Systems'' specialist-projects lead, committed to safety and Institute procedure.' AND npc_static_bio='Works under Madison Li, reviewing proposals, maintaining safety regulations and negotiating the division''s power allocation with Facilities. His cautious administrative approach often conflicts with Rosalind Orman''s more radical research ideas.' AND worldknowledge_tags='commonwealth,institute,technical_knowledge' AND personality='Strict, methodical and risk-conscious; dislikes distractions and inadequately controlled experiments.' AND occupation='Scientist and specialist-projects lead.' AND appearance='Older human man; current attire depends on observation.' AND skills='Project review, safety oversight, technical research and departmental administration.' AND speechstyle='Formal, corrective explanations that emphasize precautions and protocol.' AND goals='Keep Advanced Systems productive while preventing unsafe or wasteful work.';
UPDATE synth.bio_templates SET appearance='Human man with chestnut-brown hair, hazel eyes and a goatee; present clothing and injuries depend on the actual encounter.'
WHERE npc_name='fo4_harvey' AND core='A wary wastelander associated with the Nuka-World transit route.' AND npc_static_bio='Has firsthand familiarity with Nuka-World and the monorail linking it to the Commonwealth. Fear and the need to survive shape how he deals with strangers.' AND worldknowledge_tags='commonwealth,nuka_world,nuka_world_trade' AND personality='Nervous, cautious and eager to avoid reprisals; more candid when he feels safe.' AND occupation='Wasteland traveler with experience among Nuka-World''s traders.' AND appearance='Adult human man; present clothing and injuries depend on the actual encounter.' AND skills='Knowledge of the transit route and practical experience of the park''s trader community.' AND speechstyle='Halting, anxious and colloquial, with hurried appeals and occasional profanity.' AND goals='Stay alive and protect the few people he can rely on.';

ON CONFLICT DO NOTHING;

ON CONFLICT (plugin,baseid) DO NOTHING;

ON CONFLICT (catalog_id,catalog_version) DO UPDATE SET
display_name=EXCLUDED.display_name, checksum_sha256=EXCLUDED.checksum_sha256,
row_count=EXCLUDED.row_count, manifest=EXCLUDED.manifest
WHERE (worldknowledge_catalogs.display_name,worldknowledge_catalogs.checksum_sha256,worldknowledge_catalogs.row_count,worldknowledge_catalogs.manifest)
IS DISTINCT FROM (EXCLUDED.display_name,EXCLUDED.checksum_sha256,EXCLUDED.row_count,EXCLUDED.manifest);

SELECT seed.topic,seed.aliases,seed.topic_desc,seed.knowledge_class,seed.topic_desc_basic,seed.knowledge_class_basic,seed.tags,seed.category,seed.canonical_topic,seed.content_hash,setweight(to_tsvector('simple',coalesce(seed.topic,'')),'A')||setweight(to_tsvector('simple',coalesce(seed.aliases,'')),'A')||setweight(to_tsvector('simple',coalesce(seed.topic_desc,'')),'B')||setweight(to_tsvector('simple',coalesce(seed.topic_desc_basic,'')),'C'),'factory','fallout-4-starter-official','content-v4-2026-10-08',
COALESCE((SELECT prior.is_active FROM synth.worldknowledge prior
WHERE prior.source_kind='factory' AND prior.catalog_id='fallout-4-starter-official' AND prior.canonical_topic=seed.canonical_topic
ORDER BY (prior.catalog_version='content-v4-2026-10-08') DESC,prior.updated_at DESC,prior.entry_id DESC LIMIT 1),TRUE)
FROM (VALUES
('commonwealth','post-nuclear commonwealth','The Commonwealth is the region around Boston, Cambridge and surrounding Massachusetts towns. After the Great War, ruined roads and buildings stand beside surviving farms and communities. Caravan trade connects settlements, while raiders, dangerous wildlife and competing armed groups make travel hazardous. Local communities differ in customs, security and resources; familiarity with the region alone gives no knowledge of an individual''s private life or current events.','commonwealth_lore','The Commonwealth is the region around Boston and its surrounding towns. Settlements, farms, damaged roads and ruins share the landscape with dangerous wildlife and armed groups.','commonwealth','fallout four, commonwealth lore, location knowledge, wasteland context','location','commonwealth','f1f5e9a1453dfb71c4ac83bd789fb5e667cde82b45f93404962414c5dc9f5a4a'),
('vault_111','','Vault 111 is a Vault-Tec shelter near Sanctuary Hills. People with direct experience of its interior know it contains cryogenic pods and monitoring equipment. Residents were placed into long-term cryogenic suspension after entering during the nuclear emergency. That personal experience supports recognition of the equipment and the disruption of time; the identities, fate and private history of particular residents depend on what the character has actually learned.','vault_111_survivor','Vault 111 is a numbered Vault-Tec shelter near Sanctuary Hills. It was advertised as protection for people from Sanctuary and Concord in the event of atomic war.','prewar,commonwealth','fallout four, commonwealth lore, location knowledge, wasteland context','location','vault_111','366dfc9067b6fcb857947de34d6a5cac01200265890f5917b6403f43122a767d'),
('sanctuary_hills','Sanctuary','Sanctuary Hills is a residential neighborhood near Concord, arranged along a road ending in a cul-de-sac. Its bridge connects the neighborhood with the road toward the nearby Red Rocket stop. In the post-war period, many houses and yards are damaged, while useful structures and equipment remain. Whether survivors currently live there, who owns a particular home and what rebuilding has taken place depend on the observed settlement state.','sanctuary_postwar','Sanctuary Hills is a residential neighborhood near Concord. Houses line a road ending in a cul-de-sac, and a bridge connects the neighborhood with the road toward town.','prewar,commonwealth','fallout four, commonwealth lore, location knowledge, wasteland context','location','sanctuary_hills','a4b2a9b8abb8c61e44a2bf70f33d3f3b46638bcf993e542d4af2c6865c000de7'),
('diamond_city','','Diamond City is a major settlement inside Boston''s old baseball stadium. The market provides trade and services, while homes occupy both the former playing field and stadium stands. The Upper Stands are associated with wealthier residents and the Lower Fields with workers and poorer households. Security, news and community institutions are part of daily life, but current officeholders and individual loyalties require present knowledge.','commonwealth_lore','Diamond City is a large settlement built inside Boston''s old baseball stadium. Its walls shelter homes, shops and a central market that draws travelers and traders.','commonwealth','fallout four, commonwealth lore, location knowledge, wasteland context','location','diamond_city','a7d689178338576e7c414c0cfc3cf005e0eb0ee2da8817b017813eb011593aa6'),
('goodneighbor','','Goodneighbor is a settlement in Boston known for accepting people who feel unwelcome in other communities. Ghouls, drifters, traders and other outsiders are part of its population. Its reputation emphasizes personal freedom, and trade includes weapons and chems. This openness coexists with gangs and danger; a visitor''s safety, friendships and dealings depend on the people actually encountered rather than the settlement''s reputation alone.','commonwealth_lore','Goodneighbor is a Boston settlement with a reputation for welcoming ghouls, drifters and other outsiders. Traders and gangs share a community that values personal freedom.','commonwealth','fallout four, commonwealth lore, location knowledge, wasteland context','location','goodneighbor','347c27547d9d48adc5d225de16a6d4922f748e45ee82869cb73e7f574c09ae42'),
('sole_survivor','player,Vault 111 survivor','The traveler associated with Vault 111 can be called the Sole Survivor by people who have learned that history. A character''s knowledge of this person grows through introductions, shared experiences and information learned from others. Their present name, appearance, affiliations and companions belong to the current encounter. The title alone establishes no friendship, trust or access to the traveler''s family history.','player_acquaintance','The Sole Survivor is a title associated with the traveler from Vault 111. A person who meets the traveler learns their name and circumstances through that encounter.','player_observed','fallout four, commonwealth lore, person knowledge, wasteland context','person','sole_survivor','9f999a45a5d082baba64bf92ef97a902cf80f83a12207ee4398c529e1ce1be2b'),
('dogmeat','Dog Meat','Dogmeat is a German Shepherd known for tracking and assisting people during travel. He can accompany a traveler and help find objects or threats. People who have met him may recognize his appearance and behavior, while others need an introduction. His presence, location, condition and bond with a particular person come from the current encounter and shared experience, rather than the general fact that he can act as a companion.','dogmeat_acquaintance','Dogmeat is a German Shepherd who can assist travelers through tracking and companionship. People who have met him may recognize him, while unfamiliar people need an introduction.','dogmeat_observed','fallout four, commonwealth lore, person knowledge, wasteland context','person','dogmeat','5355c88055a1a6f4f1628fdaf5f2976d37d54980743db947b7b36d7a14466a6b'),
('synths','synth','Synth is a term for artificial humanoids associated with the Institute. Some have visibly mechanical bodies, while others resemble people closely enough to create uncertainty and fear among Commonwealth residents. Different communities and individuals disagree over whether synths are tools, threats or people. Rumors and appearances establish neither a particular person''s identity nor their intentions; recognition depends on what the character has actually observed or learned.','commonwealth_lore','Synths are artificial humanoids associated with the Institute. Some look mechanical, while stories about humanlike synths cause fear and disagreement among Commonwealth residents.','commonwealth','fallout four, commonwealth lore, faction knowledge, wasteland context','faction','synths','e5343f08e28cb7ed7a1e121fc589b6b0ea2bdfa76cad606e3975a49d5718260a'),
('brotherhood_of_steel','Brotherhood','The Brotherhood of Steel is a military organization concerned with advanced technology and the dangers it can pose. Its forces use a hierarchy of ranks, specialized technical personnel and heavily armed soldiers, including power-armored troops. Members value discipline and their mission, while outsiders may respond with admiration or suspicion. The strength and movements of a particular expedition, its current leadership and its relationship with local people depend on events the character knows.','brotherhood_of_steel','The Brotherhood of Steel is an armed organization associated with advanced technology, military discipline and power armor. Its patrols and expeditions can draw very different reactions from outsiders.','commonwealth','fallout four, commonwealth lore, faction knowledge, wasteland context','faction','brotherhood_of_steel','c63e95b0867c7f4167c32d54b42dce4475c800e033fdadaaeff0fb4b91a639a3'),
('the_institute','Institute','The Institute is a secretive scientific organization associated with the development of synths and other advanced technology. Its scientists place a strong value on research and technological advancement, and its treatment of synths differs sharply from that of groups seeking synth independence. Knowledge of these principles establishes no knowledge of its location, transport methods, personnel or private projects. Such particulars require direct affiliation or independently learned information.','institute','The Institute is a secretive organization associated in Commonwealth rumor with synths and mysterious disappearances. Residents often disagree about its abilities, motives and influence.','commonwealth','fallout four, commonwealth lore, faction knowledge, wasteland context','faction','the_institute','a2af7b54c627654ab5be216cf5c50cccfefe3ffb590a596163b4754748f69859'),
('the_minutemen','Minutemen','The Commonwealth Minutemen are a volunteer militia drawn from local farms and settlements. They aim to protect ordinary people from raiders, hostile wildlife and other threats, taking inspiration from the Revolutionary-era militia. Their equipment varies, with the laser musket a recognizable symbol rather than universal standard issue. Current commanders, allied settlements, available forces and successful defenses depend on the group''s actual condition and events known to the character.','minutemen','The Minutemen are a Commonwealth volunteer militia associated with defending settlements and ordinary people. Their name and symbols recall the militia of the Revolutionary era.','commonwealth','fallout four, commonwealth lore, faction knowledge, wasteland context','faction','the_minutemen','8bc7cf2fb43519f45f50ca5504d8262b6bd4c4b65671ea513a0c47fe2b617e96'),
('the_railroad','Railroad','The Railroad is a covert organization dedicated to helping self-aware synths obtain freedom from control. Secrecy and discretion are central to its work because open operations put both helpers and escapees at risk. Members regard synth independence as a cause worth defending, though individuals can disagree over methods and priorities. Public reputation gives no access to headquarters, passwords, routes, safehouses or the identities of individual agents.','railroad','The Railroad is rumored to be a secretive group that helps synths escape control. Many Commonwealth residents know little about it or hold conflicting views of its work.','commonwealth','fallout four, commonwealth lore, faction knowledge, wasteland context','faction','the_railroad','cff360038cb45de63cd670ca57d6b02ad5f180ea8a3feda8f1624d2bb0adec05'),
('deathclaw','deathclaws','Deathclaws are large, heavily muscled predators with prominent horns and powerful claws. Their speed and strength make close encounters especially dangerous, and tougher variants can be even harder to confront. Travelers treat them as serious threats and look for cover or a safe route away. This general knowledge describes the creature''s danger; its current presence, movement and target require an actual sighting or credible report.','commonwealth_lore','Deathclaws are large, fast predators with horns and powerful claws. Their strength and resilience make them dangerous even to well-equipped travelers who face them in the open.','commonwealth','fallout four, commonwealth lore, creature knowledge, wasteland context','creature','deathclaw','23a4bd8918f4c59d2e2a1d13989853230fc8754bd90dfc001b6b0f8b2e6ab9a9'),
('feral_ghoul','feral ghouls','Feral ghouls are ghouls whose minds have deteriorated and who attack with violent, instinctive behavior. Many lurk in damaged buildings or hazardous places and can suddenly rush a target. Groups can overwhelm a traveler through speed and numbers. They are distinct from reasoning ghouls, who retain their personalities and ability to communicate; knowing that ferals are dangerous does not establish hostility or ferality in another ghoul.','commonwealth_lore','Feral ghouls are dangerous attackers whose minds have deteriorated. They can rush travelers in groups, while reasoning ghouls remain individuals capable of ordinary conversation and relationships.','commonwealth','fallout four, commonwealth lore, creature knowledge, wasteland context','creature','feral_ghoul','c20ba9734ca3395c26806dffb1b3970cc54f96cb2c68558fe3a35e4518f8927c'),
('super_mutant','super mutants','Super mutants are large, powerful humanoids encountered across the Commonwealth. Many carry firearms or heavy weapons and occupy fortified ruins in groups. Their physical strength and aggressive behavior make such groups dangerous to travelers, but individuals differ in intelligence, speech and disposition. The identity and attitude of a particular super mutant depend on the actual encounter rather than a blanket assumption based on appearance.','commonwealth_lore','Super mutants are large, strong humanoids often encountered in armed groups around Commonwealth ruins. Individual intelligence and disposition vary, so an actual encounter determines a person''s behavior.','commonwealth','fallout four, commonwealth lore, creature knowledge, wasteland context','creature','super_mutant','79f7176927e4dec88147a9238888972ae54c354956b1679aee593429ae10a1af'),
('bunker_hill','Bunker Hill Monument','Bunker Hill is a walled caravan trading settlement surrounding a surviving granite monument in Charlestown. Its market offers supplies, medical care, food and lodging. Caravan traffic makes it an important meeting point for merchants and travelers. Residents rely on practical arrangements to protect commerce in a dangerous region, and visiting caravans change over time.','commonwealth_lore','Bunker Hill is a Commonwealth trading town built around a tall monument. Caravans use its market, and travelers can find supplies and services there.','commonwealth','commonwealth trade, caravan routes, boston settlements, regional landmarks','location','bunker_hill','4e978994daa22e0506658c77bde95098706e7b18548010582a2168ed6d81ff1c'),
('the_slog','Slog','The Slog is a tarberry farm established by Wiseman at an old public swimming pool. Its ghoul residents cultivate the waterlogged crop and welcome trade. Wiseman hopes a successful, productive community will challenge the prejudice faced by ghouls. Working conditions can be muddy and demanding, but the farm gives its residents a livelihood and a home.','commonwealth_lore','The Slog is a ghoul-run tarberry farm using an old swimming pool. Its residents earn a living through farming and trade with Commonwealth travelers.','commonwealth','ghoul communities, commonwealth farming, tarberry cultivation, regional settlements','location','the_slog','0973d5bb3e7674818333544d832a2a4fe8539a4f6ed7856843f74fe6b3d10fa6'),
('graygarden','Gray Garden','Graygarden is a self-sufficient hydroponic farm operated by Mister Handy robots. Supervisors White, Greene and Brown oversee workers tending its greenhouse and outdoor crops. Completed shortly before the Great War, the facility continued operating for generations without human supervision. Its water supply comes from the Weston treatment plant, making water quality and maintenance essential to the farm.','commonwealth_lore','Graygarden is a greenhouse and farm run by Mister Handy robots. Robot supervisors direct cultivation and maintenance, and the facility grows several useful food crops.','commonwealth','robot farming, hydroponic gardens, commonwealth produce, agricultural maintenance','location','graygarden','e40033287c7ab17ef269e0f47a50e95b2f7e8c8536bf2446a0fefc8bca9281d7'),
('drumlin_diner','Drumlin shop','The Drumlin Diner is a small roadside diner southeast of Concord that has been adapted for trading. Its oval building and surrounding parking area survive from the pre-war business. Trudy operates a shop there, with her son Patrick nearby at the beginning of the local encounter. Travelers may find caravan traffic in the area; current people and trading arrangements depend on local events.','commonwealth_lore','The Drumlin Diner is a small former diner near Concord used as a trading stop. Its roadside position makes it a recognizable landmark for travelers.','commonwealth','roadside trading, northwest commonwealth, local merchants, prewar buildings','location','drumlin_diner','1b2eff521acb8c1abc274b72c63b293cf17a0161fdf8841ba9c2443538780c7c'),
('abernathy_farm','Abernathy homestead','Abernathy farm is a family homestead built around the frame of a high-voltage electricity pylon. The makeshift farmhouse has two stories, with cultivated fields of tatos and melons around it. Blake and Connie Abernathy and their daughter Lucy work the farm. Like many small Commonwealth farms, its livelihood depends on sustained labor and protecting crops and family from local threats.','northwest_commonwealth','Abernathy farm is a family-run farm beneath a large electricity pylon. Its fields grow tatos and melons, and the tower supports its distinctive farmhouse.','commonwealth','family farming, northwest commonwealth, tato cultivation, rural settlements','location','abernathy_farm','577e60463657a0be35c350c0994109d1635e8fb33a91b9581655fcd06ca4ebc2'),
('concord','Town of Concord','Concord is a historic town northwest of Boston. The Museum of Freedom, church, shops and main street reflect its former role as a tourist destination commemorating the American Revolution. In the post-war Commonwealth, many buildings are boarded up or damaged, while scavengers and other travelers move through the ruins. Present occupants and recent fighting vary with events in the region.','northwest_commonwealth','Concord is a town northwest of Boston with a main street, church and Museum of Freedom. Its Revolutionary War history was celebrated before the bombs.','commonwealth','northwest commonwealth, revolutionary history, ruined towns, regional landmarks','location','concord','9e100bbef039308afbfa3dd48a32711e1eb32510a132b4293b8c389562027911'),
('museum_of_freedom','Concord Museum','The Museum of Freedom stands in Concord and preserves exhibits about American military history. Before the Great War it drew visitors interested in the Revolution and the sacrifices of soldiers across different eras. Its displays include mannequins and an automated audio tour. The surviving building is a recognizable landmark, while its current condition and occupants follow the situation in Concord.','northwest_commonwealth','The Museum of Freedom is Concord''s military-history museum. Its exhibits commemorate American conflicts, especially the Revolution, and it was a popular attraction before the Great War.','commonwealth','concord history, military museums, revolutionary exhibits, regional landmarks','location','museum_of_freedom','05b56181050b547ceb192fb22f581558f01a58eb630cc871bbb974fc3428a817'),
('lexington','Town of Lexington','Lexington is a town northwest of Boston with a surviving commercial district and the prominent Corvega assembly plant nearby. Its streets include shops, apartments and older service businesses. The post-war town contains dangerous ruins and has been associated with raider activity and feral ghouls. Local danger should be understood as a reason for caution rather than certainty about who occupies a particular street today.','northwest_commonwealth','Lexington is a ruined town northwest of Boston, near the Corvega assembly plant. Travelers often approach its streets cautiously because of the region''s dangerous reputation.','commonwealth','northwest commonwealth, industrial towns, urban scavenging, regional hazards','location','lexington','d26a49e2dc56f7305d460f087a0cda9f1df01b25aa04d9612405b8ec26e49207'),
('corvega_assembly_plant','Corvega factory','The Corvega assembly plant is a large automobile factory on the southern side of Lexington. Its industrial machinery, elevated structures and broad factory floors reflect the area''s pre-war manufacturing economy. The ruins have become associated with organized raider activity. The building''s size and many approaches make it a difficult place to assess from outside; current control and safety depend on recent local events.','northwest_commonwealth','Corvega is the large former automobile factory near Lexington. Its industrial ruins are a recognizable landmark, and the site has a dangerous reputation among travelers.','commonwealth','automobile factories, lexington industry, raider territory, industrial ruins','location','corvega_assembly_plant','72834cb083ed5469d7ea937af20f8ad6281c83d4ba1d6a0981e83c172f224531'),
('cambridge_police_station','Cambridge PD','Cambridge Police Station is a surviving law-enforcement building in Cambridge. Before the Great War it served police personnel from the surrounding area and Boston. In the post-war Commonwealth, the Brotherhood''s Recon Squad Gladius has used the station as a forward base and listening post. Its precise personnel, readiness and current security depend on observed Brotherhood activity rather than the building''s history alone.','brotherhood_of_steel','Cambridge Police Station is an old police building in Cambridge. It is known as a location used by Brotherhood reconnaissance personnel operating in the Commonwealth.','commonwealth','cambridge landmarks, brotherhood reconnaissance, police buildings, military outposts','location','cambridge_police_station','c9d30b23f99aec0586c29a89d6d974e2e39f4337854f65ba9f5d1baceed5152a'),
('glowing_sea','The Glowing Sea','The Glowing Sea is the intensely irradiated region southwest of Boston. Despite its name it is a devastated landscape rather than an ordinary body of water. Local stories associate it with the nuclear blast that struck the area during the Great War. Its radiation, damaged terrain and mutated wildlife make travel exceptionally hazardous for anyone lacking suitable protection and preparation.','commonwealth_lore','The Glowing Sea is a highly radioactive wasteland southwest of Boston. Commonwealth travelers regard it as exceptionally dangerous because of radiation and mutated wildlife.','commonwealth','radiation hazards, southwest commonwealth, nuclear devastation, dangerous wilderness','location','glowing_sea','b233fe6ec7d3c11ae8c296fc71710485c68f7f9408ea9db0cd915575bd96ebf6'),
('quincy_ruins','Quincy','Quincy is a historic town in the southeastern Commonwealth, with shops, a church and an elevated highway crossing its streets. Its post-war community suffered a disastrous Gunner attack remembered as the Quincy Massacre. The event scattered survivors and damaged confidence in the Minutemen. Detailed accounts belong to witnesses, and the site''s current occupation follows later events rather than remaining fixed forever.','minutemen','Quincy is a southeastern Commonwealth town remembered for the Gunner attack that devastated its community. The massacre left survivors displaced and badly harmed the Minutemen''s reputation.','commonwealth','quincy history, minutemen losses, gunner attacks, displaced communities','location','quincy_ruins','2796c47f1479349337742723084d175469e2951b85b4494903c978b8896afa39'),
('the_castle','Fort Independence,Castle Island fort','The Castle is the Commonwealth name for Fort Independence, a star-shaped coastal fort in Boston Harbor. Its thick walls enclose a courtyard and rooms within the fortifications. It once served as Minutemen headquarters and housed a powerful radio transmitter. Damage and wildlife have made the old stronghold hazardous at times; its present ownership, defenses and broadcasts depend on the current situation.','minutemen','The Castle is an old coastal fort in Boston Harbor, formerly called Fort Independence. It has a history as the Minutemen''s headquarters and a radio relay site.','commonwealth','coastal fortifications, minutemen history, boston harbor, radio infrastructure','location','the_castle','66ef7af24e3766f6d779f007d298f60e66d9746fad656209b8faff084bdd1cd6'),
('diamond_city_radio','DCR','Diamond City Radio broadcasts music, advertisements and Commonwealth news from a small studio in Diamond City. Travis Miles is its usual host at the beginning of the regional story, supported by local sponsors and listeners. The signal is widely heard across the Commonwealth. A broadcast is a report from its speaker, so claims about recent events retain that source and their original uncertainty.','commonwealth_lore','Diamond City Radio is a Commonwealth station carrying music, local advertisements and news from Diamond City. Many travelers listen on ordinary radios or their Pip-Boys.','commonwealth','commonwealth broadcasts, local news, radio music, diamond city','culture','diamond_city_radio','77cf0f09394ba0909075126fb4e9b88da39b1f988aedb5d5d5192f0ca421919d'),
('commonwealth_raiders','raiders,raider gangs','Commonwealth raiders are separate gangs rather than one unified organization. They take supplies through theft, violence and extortion, and may occupy ruined buildings or fortified camps. Some use turrets and salvaged power armor. Relationships between gangs vary: cooperation, rivalry and open fighting all occur. A gang''s actual leader, territory and intentions belong to local knowledge and current encounters.','commonwealth_lore','Raiders are gangs that prey on travelers and settlements for supplies and power. Commonwealth groups have separate leaders and rivalries, with equipment varying from improvised weapons to heavy machinery.','commonwealth','raider gangs, settlement threats, wasteland crime, local rivalries','faction','commonwealth_raiders','6b956e5db813d959a00e34ef7b6f54cd163d052a68ab03a4fdde711ddd3f6f41'),
('gunners','Gunner mercenaries','The Gunners are a heavily armed mercenary organization with military-style ranks, disciplined units and fortified positions. They use equipment such as energy weapons, power armor and combat robots, making them a serious threat to less organized communities. Their attack on Quincy is part of the Commonwealth''s recent history. Specific contracts and commanders require direct evidence or knowledge held by those involved.','commonwealth_lore','The Gunners are organized, well-equipped mercenaries operating in the Commonwealth. Their military methods and willingness to use force make them dangerous opponents for settlements and travelers.','commonwealth','mercenary forces, military organization, commonwealth threats, gunner equipment','faction','gunners','8ac3156f0a9e8773de6aee2a52a0853813d843803e14f73b1a6c85a655d3e47f'),
('atom_cats','Atom Cat gang','The Atom Cats are power-armor enthusiasts associated with a garage near Quincy. Their style combines customized armor, greaser clothing and a distinctive sense of cool. Zeke leads the group, with members such as Rowdy handling practical work around the garage. Poetry and social life matter alongside machinery, and their local cooperation with Warwick homestead is a practical neighborhood connection.','commonwealth_lore','The Atom Cats are a local group known for power armor, garage work and greaser style. Their garage is a gathering place for enthusiasts in the southeastern Commonwealth.','commonwealth','power armor culture, garage communities, southeastern commonwealth, local cooperation','faction','atom_cats','508bf243d94500b5b9131e8a07d660cf7082a6e3e8f5df05d7b052128abc510a'),
('children_of_atom','Atom worshippers,Church of the Children of Atom','The Children of Atom are religious communities that revere Atom and attach spiritual meaning to radiation and nuclear division. Some seek homes and shrines in irradiated areas. Their congregations differ in leadership and behavior, ranging from peaceful believers to aggressive zealots. Individual beliefs and a congregation''s attitude toward outsiders matter more than a single assumption about every member of the faith.','commonwealth_lore','The Children of Atom worship Atom and regard radiation as spiritually important. Their local congregations vary, so travelers judge particular groups by their conduct and teachings.','commonwealth','atom religion, radiation beliefs, wasteland congregations, local spiritual traditions','faction','children_of_atom','72300852051f46ae530389e1e43f42e3be2cd24ee5178ec4a8e115045c40f0ca'),
('great_war','the bombs,nuclear war of 2077','The Great War was the worldwide nuclear catastrophe of October 23, 2077. It destroyed the pre-war order and left cities, infrastructure and ecosystems devastated. Survivors sheltered where they could, while later communities grew among the ruins. Commonwealth residents inherit its consequences through radiation, scarcity and abandoned technology; eyewitness experiences belong to those who actually lived through the day.','commonwealth_lore','The Great War was the nuclear catastrophe in 2077 that destroyed the old world. Its ruins and radioactive aftermath shape life across the present Commonwealth.','commonwealth','nuclear history, prewar collapse, wasteland origins, commonwealth history','history','great_war','17767da655cb6a02901bcaf76512b69bb34b5d04dfa9503db65172f68a8eb447'),
('nuka_cola','','Nuka-Cola is a popular American soft drink with recognizable bottles, vending machines and advertising. Its sweet, caffeinated cola flavor helped make the brand a familiar part of daily life. Several varieties are associated with the company, and collectors can take an interest in its merchandise. The availability, condition and effects of a particular bottle depend on the item actually encountered.','prewar_culture','Nuka-Cola is a famous American soft drink associated with recognizable bottles, advertisements and vending machines. Its sweet, caffeinated cola flavor made the brand widely familiar.','prewar,commonwealth','prewar beverages, american advertising, scavenged goods, soft drink culture','food_drink','nuka_cola','ac97c5ae96931220317fcb31ffa290adc2d82566c4b6dc8e0bb52fc7bf810104'),
('robco_industries','RobCo','RobCo Industries is a major electronics and robotics company. Its products include Pip-Boys, Protectrons, computer systems and other automated equipment. RobCo technology appears in homes, businesses and public facilities, and its branding identifies many familiar terminals. Knowledge of the brand gives general familiarity; operating, repairing or identifying a particular model depends on the user''s training and the machine''s condition.','robotics','RobCo is an electronics company associated with Pip-Boys, terminals and Protectron robots. Its branding identifies many automated products and electronic systems used in businesses and public facilities.','prewar,commonwealth','prewar electronics, robot manufacturers, computer terminals, industrial brands','organization','robco_industries','27f0383db903dd06b7085b47e1b5296fab3dcf1613f91e1e684d893988e0eefb'),
('general_atomics_international','General Atomics,GAI','General Atomics International is a manufacturer associated with nuclear technology and robots, including the Mister Handy family. Different models serve domestic, caregiving and military roles. A shared manufacturer establishes a connection between products but does not establish identical personalities or abilities. Identifying a particular robot''s equipment, duties and operating condition requires familiarity with that model or direct observation.','robotics','General Atomics is a manufacturer known for Mister Handy robots and related models. Its domestic, caregiving and military robots are recognizable products serving different roles.','prewar,commonwealth','robot manufacturing, prewar industry, domestic automation, nuclear technology','organization','general_atomics_international','b15b736636befe24a703192128b7fae317ba69e3fe0cdb888d59a6e9d2c5354c'),
('vault_tec','Vault Tec Corporation','Vault-Tec is a corporation associated with constructing underground Vault shelters and equipment for their residents. Its advertising promises protection from catastrophe. Vault doors, numbered jumpsuits and shelter equipment carry its distinctive branding. Public familiarity with the company and its advertised shelters gives no automatic knowledge of any particular Vault''s occupants, interior, operating instructions or private purpose.','prewar_culture','Vault-Tec builds underground shelters called Vaults and supplies their equipment. Its distinctive branding identifies Vault doors, numbered jumpsuits, shelter advertisements and products intended for Vault residents.','prewar,commonwealth','vault construction, prewar corporations, civil defense, shelter equipment','organization','vault_tec','ceb70e59038d491e5df1bd6e63b275d6668559eecf644eb25b27ef6e9adadbf0'),
('radiation','rads,radioactivity','Radiation is a persistent hazard in the Commonwealth, including contaminated areas, water and certain scavenged food. Exposure can harm people and contribute to sickness, making protective equipment and suitable medical treatment valuable. Wasteland creatures and individual people react differently to irradiation. A nearby person''s actual exposure or illness comes from observed condition, medical information or their own account rather than a general warning alone.','commonwealth_lore','Radiation can contaminate Commonwealth water, food and ruins. Travelers use protective gear and medical supplies to manage exposure, with particular danger in heavily irradiated areas.','commonwealth','wasteland hazards, contaminated water, radiation sickness, travel preparation','concept','radiation','c6034ad2fc1939c591c961ecdb92939d86e968d218239e103f72ff74368472f4'),
('radstorms','radstorm,radiation storms','Radstorms are dangerous weather systems associated with the Glowing Sea southwest of the Commonwealth. Green haze and lightning make them visually distinct from ordinary cloudy weather. They expose unprotected travelers to radiation and can reduce visibility. Commonwealth weather also includes normal rain and fog, so a character identifies a current radstorm from the observed environment rather than assuming every storm carries radioactive fallout.','commonwealth_lore','Radstorms bring green haze, lightning and radiation from the direction of the Glowing Sea. Travelers treat them as a hazard distinct from ordinary rain or fog.','commonwealth','radiation weather, green lightning, commonwealth storms, environmental hazards','concept','radstorms','385c1320f64254034044e71e1740cb53dfac244da3b8d8c2901e65fffc309102'),
('brahmin','pack brahmin','Brahmin are two-headed cattle central to wasteland farming and trade. People keep them for milk, meat, hides and fertilizer, while caravans use them to carry supplies. Their hardy nature makes them useful in difficult conditions. A particular animal''s owner, cargo, health and behavior are local facts established by observation; the species'' economic importance explains why settlers and traders value them.','commonwealth_lore','Brahmin are two-headed cattle used as livestock and pack animals. Their milk, meat, hides and fertilizer support settlements, and caravans rely on them to carry trade goods.','commonwealth','wasteland livestock, caravan animals, settlement agriculture, trade supplies','creature','brahmin','6d3ae5154b1e64da21e69ea7f326cd22dbc58942ac73bd6f6fd28bf5d646defa'),
('radstag','radstags','Radstags are mutated descendants of local deer, recognizable by two heads, patchy coats and small extra forelimbs. Many move in small herds and flee from people, but cornered or aggressive animals can gore an opponent with their antlers. Travelers and hunters judge an individual animal by its behavior and condition; the general species description gives useful recognition without establishing hostility in every encounter.','commonwealth_lore','Radstags are two-headed mutated deer found in the Commonwealth. Many shy away from people, though an aggressive or cornered animal can be dangerous at close range.','commonwealth','mutated deer, woodland wildlife, animal behavior, commonwealth hunting','creature','radstag','fa7cbff9123bf17e108df35153ccfe575454a3febc1779c3ee47d084017c301e'),
('mirelurk','mirelurks','Mirelurks are dangerous creatures associated with shores, water and muddy ground. Common varieties have thick shells and large claws, while hunters, kings and queens differ in shape and abilities. Shelled mirelurks protect much of their body behind hard armor, with the face comparatively exposed. Their tendency to gather and conceal themselves makes caution useful near nests and coastal ruins.','commonwealth_lore','Mirelurks are dangerous waterside creatures, often recognizable by shells and claws. Several varieties exist, and armored ones can be difficult to fight when their vulnerable areas remain covered.','commonwealth','coastal wildlife, armored creatures, waterside hazards, mirelurk varieties','creature','mirelurk','3be0eb8695fc17410f9a4dc34cb58f89a86f70d4f6b04db648f060d6bb2a6381'),
('bloatfly','bloatflies','Bloatflies are oversized mutated flies found around Commonwealth ruins and open country. They can rest on trees, walls and pipes before taking flight, and are frequently encountered in small groups. Their enlarged bodies rely on unusual adaptations, including a gland studied by local scientists. Travelers regard them as pests and potential threats, with the actual danger depending on the creature''s variant and behavior.','commonwealth_lore','Bloatflies are large mutated flies commonly found around ruins and wooded areas. They may cling to surfaces or gather in small groups, making them a familiar wasteland pest.','commonwealth','mutated insects, wasteland pests, flying creatures, commonwealth wildlife','creature','bloatfly','a70481df592fae27ff99c35cfe31003bad49b92b02138aa1350b7f44610dda1c'),
('mole_rat','mole rats','Mole rats are enlarged, hairless rodents with prominent front teeth. Commonwealth specimens tunnel underground and burst through the surface to attack, making their movement difficult to follow. They can be territorial and troublesome in groups. A few wastelanders have kept trained animals, so an individual''s behavior and allegiance come from the encounter rather than the species name alone.','commonwealth_lore','Mole rats are large mutated rodents that tunnel below ground and emerge suddenly. Travelers watch for disturbed soil and groups of animals when moving through their territory.','commonwealth','burrowing animals, mutated rodents, underground ambushes, wasteland pests','creature','mole_rat','590f08428e0bf2add8716ab31e0710d2be53f8b44214de23c2501aba02d9f773'),
('radroach','radroaches,giant cockroaches','Radroaches are enlarged mutated cockroaches found in Commonwealth buildings and neglected spaces. They can hide behind furniture or on walls and ceilings, then leap or swarm when disturbed. Individual animals are generally less formidable than the region''s larger predators, but groups remain a hazard. Their appearance and movement offer recognition cues; exact infestation and danger come from the place being inspected.','commonwealth_lore','Radroaches are giant mutated cockroaches found in neglected buildings. They hide around furniture and surfaces, then may leap or swarm when something disturbs them.','commonwealth','mutated cockroaches, indoor pests, abandoned buildings, insect swarms','creature','radroach','0770fa81ab579c61cce15e6aa475262cb4c4c4ca954a54180e4fa1ce23f06fef'),
('stingwing','stingwings','Stingwings are large flying insects with a scorpion-like tail ending in a venomous sting. Their fast, erratic flight and repeated attacks make them difficult to handle, especially in groups. They may defend nests attached to ground or walls. Recognizing a stingwing''s shape helps explain the hazard, while the presence of a nest or an attack requires evidence from the current surroundings.','commonwealth_lore','Stingwings are fast mutated flying insects armed with venomous stingers. Groups can attack fiercely, and their erratic movement makes them a dangerous Commonwealth insect hazard.','commonwealth','venomous insects, flying predators, insect nests, commonwealth wildlife','creature','stingwing','beabd6de8ff7711917289335b27182be26356342d3c3e97078c481fb66e74636'),
('yao_guai','yao guai bears','Yao guai are large mutated descendants of American black bears. Their strength, claws and teeth make them formidable close-range predators, and wild individuals can attack people or other animals. Family groups may show bonds among themselves. Their reputation encourages travelers to keep a respectful distance, while the behavior of a particular animal remains something to assess in the actual encounter.','commonwealth_lore','Yao guai are powerful mutated bears with dangerous claws and teeth. Wild specimens are serious threats, particularly at close range, and deserve caution when encountered.','commonwealth','mutated bears, large predators, woodland danger, animal behavior','creature','yao_guai','598aac265e4ddc3089950ab22d5e55176abcfb83b48012ec3b3054f62410d369'),
('protectron','Protectrons','Protectrons are RobCo''s bipedal service robots, built for work such as security, construction and public assistance. Models and software personalities differ with their assigned purpose. Their compact bodies, dome-like heads and deliberate movement make them recognizable. Units can still follow old routines; an individual machine''s active instructions, identification requirements and attitude toward visitors must be learned from that unit or its controls.','robotics','Protectrons are pre-war RobCo service robots used for security, construction and other duties. Their body shape and slow movement are recognizable, while particular units follow their own assigned routines.','prewar,commonwealth','service robots, robco technology, automated security, robot personalities','robot','protectron','f86f05b697a3341175be9fda7f1d3c74bac973990f3ce1b704bfbdada5135876'),
('mister_handy','Mr. Handy,Mister Handies','Mister Handy robots were developed as general-purpose domestic and maintenance assistants by General Atomics. The familiar later design floats above the ground with multiple arms and tools for household work. Units can speak, and some show considerable initiative and personality. Related models were adapted for caregiving and military duties. Each robot''s memories, temperament and present role belong to that individual.','robotics','Mister Handy is a pre-war floating utility robot associated with General Atomics. Its arms, tools and speech capabilities made it useful for household work and maintenance.','prewar,commonwealth','domestic robots, general atomics, household automation, robot individuality','robot','mister_handy','9fc39716ac8d3ecd85a94b5563598f6a9bbbdb973149e73fd9ef8a2dc1f07869'),
('assaultron','Assaultrons','Assaultrons are agile combat robots with humanoid frames. Their close-range speed and powerful head-mounted energy weapon make them far more dangerous than ordinary service machinery. Some specialized models can conceal themselves before striking. Actual units may serve different owners and roles, so recognizing the design signals capability while its present allegiance and behavior come from the encounter.','robotics','Assaultrons are fast combat robots with dangerous close-range attacks and a head-mounted energy weapon. Their military design warrants caution even when a particular unit appears inactive.','prewar,commonwealth','combat robots, energy weapons, robotic mobility, automated military technology','robot','assaultron','d1be6b172420c76e6e9b4e38740466eecbe7320c71fbae53a98d0a877f61b91d'),
('stimpak','stimpaks,stimpack','A stimpak is an injectable medical package used to treat injuries. Its familiar form combines a syringe with a gauge monitoring its contents. It can help with wounds and injured limbs, making it a valuable part of a traveler''s medical supplies. Treatment still depends on having and using an actual dose; an offer to help or general medical knowledge describes intent rather than an already completed intervention.','medicine','Stimpaks are syringe-based medical supplies used for healing injuries. Travelers value them for treating wounds and damaged limbs when an actual dose is available and administered.','prewar,commonwealth','medical supplies, injury treatment, injectable medicine, wasteland first aid','medicine','stimpak','558d9dc0ff3b7b0385877efc3d891711e2d29ec052a219445d1fa598895ce5d7'),
('fusion_core','fusion cores','Fusion cores are standardized nuclear power sources used in military and commercial equipment. Compatible cores supply power armor, generators and certain heavy energy weapons. Their portable form and shared interfaces make them valuable salvage for people who work with advanced machinery. A particular core''s charge, ownership and availability follow inspection and inventory information, while access to one alone does not establish that any device has been repaired or activated.','technical_knowledge','Fusion cores are portable nuclear power sources associated with power armor and advanced machinery. Suitable cores can be valuable to mechanics and travelers using compatible equipment.','prewar,commonwealth','nuclear batteries, power armor, energy equipment, technical salvage','technology','fusion_core','bdbd63965cd72a747bc9c19a2cf63a014cb367948f55556ddd4778c280eb885c'),
('power_armor','powered armor,power armour','Power armor is a powered frame fitted with protective armor pieces. It enhances the wearer''s physical capabilities and uses a fusion core for power in common Commonwealth configurations. Models differ in design and protection, and damaged pieces can require repair at an appropriate station. A visible suit''s model, markings, condition and wearer come from observation; wearing it signals equipment capability rather than a guaranteed faction allegiance.','technical_knowledge','Power armor is heavy protective equipment built around a powered frame. Its armor pieces, power supply and maintenance distinguish it from ordinary clothing or body armor.','prewar,commonwealth','powered equipment, protective armor, fusion power, armor maintenance','technology','power_armor','adcf938cbc05b652e7f7e1389557f493f02f1a05d2419b8de4d08520e437798a'),
('radaway','Rad-Away','RadAway is a medical supply used to remove accumulated radiation from the body. In the Commonwealth it is valuable to people exposed to contaminated food, water or dangerous areas. It treats existing exposure rather than serving as ordinary protective clothing. A person''s need for treatment and the result of using a dose depend on their actual condition and what has happened in the present encounter.','medicine','RadAway is used to reduce radiation already accumulated in a person''s body. Travelers value it after exposure to radioactive water, food or hazardous areas.','prewar,commonwealth','radiation treatment, medical supplies, exposure recovery, wasteland first aid','medicine','radaway','6770cbbbdd07ec588690d56fc84034a66d6d5bcd9023f68e63ef502debb582a6'),
('commonwealth_farming','farm work,settlement farming,farmer','Commonwealth farming supports households, settlement markets and caravans. Farmers tend crops such as tatos, mutfruit, corn, carrots, gourds, melons and razorgrain, while some sites specialize in greenhouse growing or tarberries. Crops need people to work them and a reliable water supply; livestock can contribute fertilizer. Field work, harvesting and protecting food supplies give farming communities a reason to cooperate. A farm''s present harvest, workers and trading arrangements depend on its actual condition.','farmer,agriculture','Farms grow food for Commonwealth settlements and trade. Familiar crops include tatos, mutfruit, corn, carrots, gourds, melons and razorgrain. Farmers rely on water, labor and protection.','commonwealth','commonwealth agriculture, crop cultivation, settlement food, farm labor, agricultural livelihoods','concept','commonwealth_farming','9bbf6cb81d7bcebbf7190eadd4da4f873572a61384d1132cfa94a8ed1088d6ff'),
('commonwealth_caravan_trade','caravan trading,traveling merchants,trader','Commonwealth merchants buy and sell supplies through settlement shops and traveling caravans. Diamond City and Bunker Hill provide established markets, while roadside traders connect smaller communities. Old Man Stockton''s Bunker Hill caravan business is a prominent trading operation. Traveling merchants may specialize in weapons, armor, medical aid or general goods, with guards and pack brahmin accompanying the familiar caravans. Stock and available caps vary, so reputation alone does not establish what a merchant has today.','trader,caravan_trade','Caravans and settlement shops move goods around the Commonwealth. Traders sell supplies, and familiar caravans travel with guards and brahmin carrying their stock.','commonwealth','commonwealth trade, caravan routes, traveling merchants, settlement markets, brahmin transport','concept','commonwealth_caravan_trade','d5d0c57e28279b12a6639f61206ae49e00f108b9cda64c710a1439242fa1e11b'),
('commonwealth_doctors','wasteland doctor,medical services,doctor','Doctors in the Commonwealth offer treatment for injuries, radiation exposure and chemical addiction. Many also sell medical supplies. Established communities can support clinics, while traveling doctors bring services to people along caravan routes. The service offered depends on the practitioner and available facilities; a trade in medicine alone does not prove the seller is a trained physician. Diagnosis, treatment and payment require an actual encounter rather than merely recognizing a clinic or medical item.','medicine,doctor','Commonwealth doctors treat injuries, radiation exposure and addiction. Clinics and traveling physicians provide care, and many doctors also sell medical supplies.','commonwealth','commonwealth clinics, wasteland medicine, traveling doctors, radiation treatment, medical services','concept','commonwealth_doctors','611e2b70b04696f14ef7a9eb7fd18f223448e56e35981a2165ce7f9acadc9032'),
('power_armor_maintenance','armor servicing,power armor station,mechanic work','Power armor maintenance uses a station that supports a powered frame while armor sections are inspected, repaired or modified. Commonwealth stations include a large box-frame style with hydraulic supports and a smaller two-strut style. Suitable armor parts, materials and technical skill determine which work can be done. Repair and modification are separate from supplying a fusion core; having a station nearby does not mean a damaged suit has already been serviced.','technical_knowledge,mechanic','Power armor stations help mechanics repair and modify armor fitted to a powered frame. Repairs require suitable parts, materials and someone able to perform the work.','prewar,commonwealth','power armor servicing, armor repair stations, mechanical maintenance, powered frames, armor components','technology','power_armor_maintenance','44b68fd227c6a62196045c3441311cf3b6aab43b7710d7cf54c0ebfebcd30a4d'),
('commonwealth_militia_service','militia duty,settlement soldier,minuteman service','The Commonwealth Minutemen grew from settlers volunteering to defend their homes and neighboring communities. Militia service joins ordinary settlement life with armed protection, rather than separating every fighter into a permanent professional army. Responding to threatened homesteads, helping communities prepare defenses and supporting other settlers are central to the group''s purpose. A particular unit''s strength, orders, patrols and allegiance depend on present events and cannot be inferred from the Minutemen''s older reputation.','minutemen,soldier','Minutemen serve as a volunteer militia protecting Commonwealth homes and settlements. Ordinary settlers can take up arms to help their neighbors when danger threatens.','commonwealth','commonwealth militia, settlement defense, volunteer soldiers, minutemen service, neighboring communities','concept','commonwealth_militia_service','a73c5ed34216fc815435cc22c4c64369e2aa78088c5681f0967288371193df4a'),
('vault_81','Vault Eighty-One','Vault 81 is an inhabited Vault-Tec shelter whose residents trade with the Commonwealth. Its ordinary living areas include an atrium, depot, cafeteria, barber, clinic, classroom and hydroponics facilities. Generations of residents have kept the shelter functioning, but obtaining supplies and repairing aging equipment remain practical concerns. Visitors encounter security and admission procedures before entering the community. Familiarity with its public trading role gives no knowledge of restricted areas or individual residents'' private affairs.','vault81_lore','Vault 81 is an inhabited underground shelter that trades with Commonwealth outsiders. Its residents live behind a Vault door and maintain their own community and services.','commonwealth','inhabited vaults, vault 81 community, commonwealth trade, underground services, shelter maintenance','location','vault_81','b62a9a61851429799a9fe64084ba7d331475b1b3b0ce1219b92997027e6988fd'),
('finch_farm','Finch homestead','Finch farm is a small family farm beneath a ruined section of the Boston Expressway. A cottage, water pump and cooking area support fields growing mutfruit, corn and razorgrain. The overpass is a prominent landmark above the homestead. Its surroundings include other industrial ruins and hostile groups, so working the farm also involves maintaining a safe home. Current family members, protection and improvements follow local events rather than the site''s general description.','northeast_commonwealth','Finch farm is a family homestead under a ruined expressway. Its cottage and crop plots sit beneath the elevated roadway, with mutfruit, corn and razorgrain cultivated nearby.','commonwealth','finch family farm, expressway homesteads, commonwealth agriculture, northeastern settlements, cultivated crops','location','finch_farm','cb31506a05443ee0932497769e33a79b9647d86a0492ab34268da4ca526aca40'),
('warwick_homestead','Warwick farm','Warwick homestead occupies a former waste treatment plant adapted into a farming community. Its strong main building provides sleeping quarters, while walkways connect the old processing tanks and service structures. Fields grow tatos, mutfruit and gourds, supported by a water pump and cooking area. The surviving industrial equipment makes maintenance part of everyday work. The farm''s public layout and crops give no information about a particular resident''s identity or any hidden research arrangement.','southern_commonwealth','Warwick homestead is a farm at an old waste treatment plant. Fields and living quarters share the site with large processing tanks and surviving industrial walkways.','commonwealth','warwick family farm, treatment plant settlement, southern commonwealth, industrial homesteads, cultivated fields','location','warwick_homestead','f1af8ad5ddebe5dbeee98a2fc2cff3c5efa68f53699b35d30b9cbdeba04ce904'),
('tenpines_bluff','Ten Pines Bluff','Tenpines Bluff is a small northern Commonwealth farm with a shack, a tato field, a water pump and a cooking station. A damaged house stands near the cultivated area. Its modest buildings and crop work make it a recognizable rural homestead rather than a large fortified town. Traveling armor merchant Lucas Miller has included it among his stops. Present occupants, caravan arrivals and any rebuilding depend on the current settlement state.','northwest_commonwealth','Tenpines Bluff is a small farm in the northern Commonwealth. A shack and damaged house stand beside a cultivated tato field, water pump and cooking area.','commonwealth','tenpines farm, northern commonwealth, rural homesteads, tato cultivation, caravan stops','location','tenpines_bluff','42435c1e7103d23b63e01050a9493d651c54531e0d3cf7a27bf22985be799a6b'),
('county_crossing','County Crossing farm','County crossing is a small mutfruit farm near the National Guard training yard and an old nuclear power station. The homestead includes a shack, a roofless ruined house, a water pump and cooking facilities. A small pond occupies part of the area, and Doc Weathers has used the settlement as a caravan stop. Industrial and military ruins shape the surrounding landscape. The current harvest, travelers and nearby threats require recent local knowledge.','northeast_commonwealth','County crossing is a small Commonwealth mutfruit farm near old military and power facilities. Its settlers use a shack, water pump and cooking area beside the fields.','commonwealth','county crossing farm, mutfruit cultivation, northeastern commonwealth, military ruins, caravan stops','location','county_crossing','c4a69f57a63c99e0131d5a94610cdab495d14660a23f5aa214406e999e0915db'),
('jamaica_plain','Jamaica Plain ruins','Jamaica Plain is a ruined town in the southern Commonwealth, southwest of University Point and northwest of Quincy. Surviving buildings include a church and town hall among damaged homes and streets. Its reputation combines dangerous feral ghoul activity with stories of pre-war treasures, which have attracted scavengers and treasure hunters. Such stories are rumors about the site''s appeal; they establish neither the contents of an unopened room nor the fate of a particular expedition.','southern_commonwealth','Jamaica Plain is a ruined southern Commonwealth town with a church and town hall. Travelers know its dangerous reputation and stories about pre-war treasures.','commonwealth','jamaica plain ruins, southern commonwealth, ruined town hall, commonwealth landmarks, feral ghoul danger','location','jamaica_plain','023639ef2a52a51becb7b6f63ddb36e5a495b0325b50281509beb1efd1987cd4'),
('red_rocket_truck_stop','Concord Red Rocket,Sanctuary Red Rocket','The Red Rocket truck stop between Sanctuary Hills and Concord is a former coolant replenishment and vehicle service station. Its garage and distinctive Red Rocket branding make it easy to recognize from the road. A workshop and power armor station survive inside, with other crafting facilities around the building. These tools offer opportunities for maintenance and reuse if the site is secured. Its present owner, residents and working equipment depend on what has actually happened there.','northwest_commonwealth','The Red Rocket truck stop was built as a service station between Sanctuary Hills and Concord. Its garage, coolant pumps and familiar rocket branding form a roadside landmark.','prewar,commonwealth','red rocket garage, concord roadside services, northwest commonwealth, vehicle service stations, workshop equipment','location','red_rocket_truck_stop','3702800bc503e6545d822b33ef06a499832e61e244dcdb169578fff2c0d1f9ba'),
('the_island','Mount Desert Island,Island of Far Harbor','The Island is the former Mount Desert Island off the coast of Maine. Woods, marshes, rocky shores and surviving tourist or industrial buildings share a cold, wet landscape affected by radioactive Fog. Far Harbor is a coastal landing point, Acadia stands inland on high ground, and the Nucleus occupies an old submarine facility. Offshore rocks and wrecks make navigation difficult; experienced crews and suitable guidance are valuable. Conditions and safe routes can change with the Fog.','far_harbor_lore,far_harbor_navigation','The Island lies off Maine and is covered in woods, ruined buildings and radioactive Fog. Far Harbor, Acadia and the Nucleus are its main communities.','far_harbor','mount desert island, maine coastal geography, far harbor region, island navigation, radioactive fog','location','the_island','ad1127f8d035b6a1348038a13f37b1976dca9b838c44299056626b8e79b026fa'),
('far_harbor','Far Harbor town,Bar Harbor','Far Harbor is a waterfront community in the remains of Bar Harbor on the Island''s northeast shore. Island families driven from inland homesteads by the Fog gathered on the Mariner''s pier. The fortified wall called the Hull protects the town from creatures, while Fog condensers make the immediate area habitable. Trading, fishing, lodging and medical care support daily life. Its people value maritime traditions and often approach mainland visitors cautiously; present leadership and relations follow local events.','far_harbor_lore','Far Harbor is a coastal town on the Island. Its waterfront homes and shops shelter behind a wall called the Hull and machines that keep the Fog back.','far_harbor','far harbor town, coastal landing point, harbormen community, hull defenses, island commerce','location','far_harbor','8fbe35f57c568943be994d307fbfb82a7cfae273133766bb8286f7d5d33b4ff5'),
('harbormen','Far Harbor islanders,Harbor folk','The harbormen are the Island''s local people, with customs rooted in fishing, sailing and independent homesteads. They traditionally respect a community captain and prize endurance and practical service. Many families have been displaced by the Fog, concentrating their lives around Far Harbor''s pier. Boats, fishing gear and familiar ballistic weapons suit their way of life. Suspicion of mainlanders and conflict with the Children of Atom are part of their public reputation, though individual attitudes differ.','far_harbor_lore','Harbormen are the Island''s local fishing and homesteading people. They value independence, toughness and service to their community, and can be wary of unfamiliar mainlanders.','far_harbor','harbormen communities, island fishing culture, coastal livelihoods, far harbor residents, local traditions','organization','harbormen','a7812bdead86739de8b8c105a79670935aeae3a745fc9ff33c82e605a3917233'),
('acadia','Acadia observatory,synth refuge','Acadia occupies a pre-war astronomical observatory on high ground inland from Far Harbor. It is a refuge for synths seeking a community among their own kind, with farming, trading and technical work supporting daily life. Its stated aim is to coexist peacefully with other Island residents. Acadia supplied Fog condenser technology to Far Harbor in exchange for access to supplies and a safe dock. The refuge''s public purpose does not establish a stranger''s synth identity or any hidden political arrangement.','acadia_lore','Acadia is an Island community in an old observatory. It is known locally as a synth refuge whose residents express a desire to live peacefully with their neighbors.','far_harbor,acadia','acadia observatory, island synth refuge, far harbor communities, fog condenser support, mountain settlement','location','acadia','d58cf64108d57914cdd4243de4bb0845966475c6c1f6c0e40db8eb4e587f4ee0'),
('the_nucleus','Nucleus,Mount Desert Island Naval Facility','The Nucleus is the Island Children of Atom''s home in a former naval submarine facility. An old submarine, called the Vessel, dominates a large interior lined with catwalks and makeshift dwellings. The community includes shops, a clinic and work areas, with religious life centered on Atom and radiation. Irradiated water and deeper parts of the facility make environmental protection a practical concern for visitors. Knowledge of this public settlement gives no access to restricted systems or private records.','nucleus_lore','The Nucleus is the Children of Atom''s Island settlement in an old submarine facility. The submarine and surrounding catwalks, dwellings and shops form their unusual home.','far_harbor,nucleus','nucleus submarine facility, island atom worshippers, underground community, children of atom, irradiated settlement','location','the_nucleus','4d546bf24c805a962b6da3e4e590fffd3e8fe21200103d6910863246722e0d45'),
('island_children_of_atom','Nucleus Children of Atom,Island Atomites','The Children of Atom on the Island are a local congregation of the radiation-worshiping faith based at the Nucleus. They regard the radioactive Fog as a sacred manifestation of Atom rather than merely an environmental hazard. Their view brings them into conflict with harbormen who need habitable land and Fog condensers. Zealots protect the congregation and carry its message. These are beliefs and public roles, not proof that a particular adherent is immune to radiation or responsible for changing the Fog.','nucleus_lore','The Island''s Children of Atom live at the Nucleus and worship radiation. They treat the Fog as sacred, putting them at odds with Far Harbor''s need to keep it away.','far_harbor,nucleus','island atom congregation, nucleus worshippers, radioactive fog beliefs, zealot duties, far harbor tensions','organization','island_children_of_atom','e759d475524d291e36a3d3268cf5301de09d868e131f3503f267f5a5c687cff0'),
('island_fog','The Fog,Atom''s veil,Deep Fog','The Island''s Fog is a radioactive environmental hazard that limits visibility and makes travel and habitation dangerous. Its extent has risen and fallen over the generations remembered by local people. Thick patches conceal dangerous wildlife, while exposure can cause sickness. Experienced guides distinguish especially hazardous Deep Fog from clearer ground. Harbormen fear its advance, while the Children of Atom interpret it religiously. Neither interpretation establishes the Fog''s origin or the cause of a current change.','far_harbor_lore,far_harbor_navigation,far_harbor_ecology','The Island''s Fog is radioactive and obscures the land. It can make people sick, hide predators and drive families from unprotected homesteads.','far_harbor','radioactive island fog, far harbor weather, coastal navigation hazards, island ecology, atom religious beliefs','concept','island_fog','d198435492e847ea6f7137ab4796c530ee6346d91980e0fd6c4658147a4ec4d0'),
('fog_condensers','Fog condenser,Fog machines','Fog condensers are tall devices developed at Acadia and supplied to Far Harbor to clear radioactive Fog from nearby areas. Their visible design includes a light at the top and tubing that collects condensed liquid below. Protected areas still depend on working equipment and maintenance; Acadia''s technical help is part of the relationship between the two communities. A condenser''s presence does not prove that it is powered, undamaged or clearing the surrounding area at this moment.','fog_engineering','Fog condensers are machines used around Far Harbor to keep nearby radioactive Fog back. They help make protected homes and paths habitable.','far_harbor','fog condenser machines, acadia engineering, protected island settlements, far harbor defenses, equipment maintenance','technology','fog_condensers','074dfd014e83184a46fb6e966a99f79132d85c327dde6368b324e049b1ae024f'),
('island_trappers','Trappers of Far Harbor,trapper gangs','Trappers are dangerous armed groups encountered around the Island''s ruins and camps. Many were once fishers or hunters, and islanders associate their violence with long exposure to the Fog and the hardships of the Island. Trapper and coastal armor, salvaged firearms, harpoon guns and fishing-derived melee tools give them a distinct appearance. Their reputation warns travelers about hostile camps; it does not establish a current camp''s occupants or the intentions of every person wearing coastal clothing.','far_harbor_lore,far_harbor_navigation','Trappers are armed, violent groups living around Island ruins and camps. Their coastal armor and salvaged fishing gear distinguish them from many Commonwealth raiders.','far_harbor','island trapper gangs, coastal armor, hostile island camps, salvaged fishing weapons, far harbor hazards','organization','island_trappers','56a5ec9d64619ede2272a36ff18c29e5f00c56bcb1be4dc875aa8f1cc2d90ede'),
('vim','Vim soda','Vim is a soft drink associated with Maine and the Island, produced before the war by Vim! Pop Incorporated. It began as a health tonic and became a regional tradition, more popular in Maine than its larger rival Nuka-Cola. Surviving bottles, vending machines and painted branding keep the name familiar locally. Known varieties include Captain''s Blend, Quartz and Refresh. Recognizing a bottle or flavor gives no knowledge of a protected recipe or of the supplies a trader currently has.','far_harbor_lore','Vim is the Island''s familiar local soda brand. Bottles and old vending machines survive around Maine, where it was more popular than Nuka-Cola before the war.','far_harbor','vim soda brand, maine soft drinks, island beverage culture, prewar regional advertising, vim flavor varieties','concept','vim','b86f12e17e3c330c34e9d3a9e8a79f0a697d3b40e99c48e174557d5eb983f4bc'),
('vim_pop_factory','Vim! factory','The Vim! Pop factory was the company''s production and distribution center on the Island. Its complex includes corporate offices and separate mixing, bottling and shipping areas, with large vats, catwalks and industrial equipment. A bridge and waterfront structures connect the site with its surroundings. The ruins have a reputation for super mutant occupation and are dangerous to approach without current information. The factory''s public industrial history gives no knowledge of locked rooms or concealed facilities.','far_harbor_lore','The Vim! Pop factory is the Island''s old soda production complex. Offices, vats and bottling equipment survive in industrial ruins with a dangerous reputation.','far_harbor','vim bottling factory, island industrial ruins, soda production machinery, far harbor landmarks, hostile factory occupants','location','vim_pop_factory','84280fbae346e74eb17e5fdbf42ff61ed34eb54c5026c8fbb7e634e2fcfd9b08'),
('island_angler','Angler,Far Harbor anglers','Anglers are dangerous waterside creatures found on the Island. They can wait under the surface near lure weed, with a glowing growth above the head imitating the plant to draw prey close. Their attacks include claws and a fiery discharge that makes them dangerous beyond arm''s reach. Recognizing the false lure is useful to experienced travelers. The source of the species is not established by its resemblance to particular fish or amphibians.','far_harbor_ecology,far_harbor_navigation','Island anglers hide near water with a glowing lure that resembles lure weed. They ambush prey and can attack with claws and a fiery discharge.','far_harbor','island angler creatures, aquatic ambush predators, lureweed imitation, far harbor wildlife, shoreline hazards','creature','island_angler','01dbf4ed3ab1a2cf9af908feb8e5025513f29e1783bb3862a75f37d2eb0ed9c2'),
('island_gulper','Gulper,Far Harbor gulpers','Gulpers are the Island''s mutated salamanders, often associated with freshwater areas. They continue growing throughout life, so older individuals can become especially large and formidable. Some hang from tree branches by their tails and drop on passing prey. They rush opponents and attack with their large mouths and forelimbs. Knowledge of the species helps explain the risk around wooded watercourses, but the presence, size and behavior of a particular animal need an actual sighting.','far_harbor_ecology,far_harbor_navigation','Island gulpers are large mutated salamanders. They favor freshwater areas, grow throughout life and can ambush prey by dropping from tree branches.','far_harbor','island gulper creatures, mutated salamanders, tree ambush predators, far harbor wildlife, freshwater habitats','creature','island_gulper','705c6054bd512ee95c85291f331b2d4318f6fbfb0ce9609d317b184e9c29a6af'),
('island_fog_crawler','Fog crawler,Far Harbor crawlers','Fog crawlers are enormous, heavily protected predators associated with the Island''s Deep Fog. Their crustacean-like bodies rise above people, and large claws allow powerful close attacks. Deep booming calls can announce their presence even when mist obscures the animal. Despite their size and armor, they can move quickly over land. Experienced Island travelers take their reputation seriously, while a call or report must still be assessed before claiming one is nearby.','far_harbor_ecology,far_harbor_navigation','Fog crawlers are huge armored predators usually associated with the Island''s deep mist. Their large claws, speed and booming calls make them a feared local hazard.','far_harbor','island fog crawlers, armored crustacean predators, deep fog hazards, far harbor wildlife, coastal creature encounters','creature','island_fog_crawler','8ede696290b3140a347a88832e471ef7f6f98cd7748c66a0ddb5d6a70f1bc5a4'),
('nuka_world','Nuka-World amusement park','Nuka-World is a former Nuka-Cola amusement park outside Boston, divided into Nuka-Town USA and several themed areas. Its attractions celebrated space travel, the Wild West, animals, children''s entertainment and soda production. After the war, traders established a community in Nuka-Town, which later became associated with three raider gangs: the Operators, Disciples and Pack. The outer park areas contain dangerous ruins and wildlife. A local reputation does not establish which gang controls an attraction today.','nuka_world_lore','Nuka-World is an old Nuka-Cola amusement park with several themed areas. Nuka-Town USA is its trading hub and is associated with three raider gangs.','nuka_world','nuka world amusement park, prewar tourist attractions, raider occupied park, themed attraction zones, park trader community','location','nuka_world','f09a54f0c1570eac6b1c9e823d21397726bb1b06e6086c8e5c896706c014d1f3'),
('nuka_town_usa','Nuka-Town U.S.A.','Nuka-Town USA is the central hub of Nuka-World, built around eateries, entertainment venues and the market. The old Nuka-Cade, Cola-cars arena and Bradberton Amphitheater remain recognizable attractions. In the period of raider rule, the Pack is associated with the amphitheater, Operators with the Parlor and Disciples with Fizztop Mountain. Traders and laborers continue supporting the town under coercive conditions. Its current rulers, access and safety require recent knowledge of the park.','nuka_world_lore','Nuka-Town USA is Nuka-World''s central settlement and market district. Old restaurants and entertainment venues share the town with traders, laborers and raider gang camps.','nuka_world','nuka town usa, park market district, nuka world traders, gang headquarters, amusement park attractions','location','nuka_town_usa','ffa2f8fd18e162048f2e6008dbb73c3bce0ecbcd03a876de69ffdebe098411b1'),
('nuka_world_traders','Nuka-Town traders,collared traders','Nuka-World''s traders include people who lived in the park before the raider takeover. During raider rule, shock collars and threats force them to trade, perform manual labor and serve the gangs. The market''s merchants and medical provider keep essential goods and care circulating despite this coercion. Wearing a collar may show subjection, not support for the gang using it. A particular trader''s present freedom, stock and relationship with a visitor follow actual local events.','nuka_world_lore,nuka_world_trade','Nuka-Town''s traders provide goods and services under raider coercion. Shock collars have been used to control them, so their forced work does not imply loyalty to the gangs.','nuka_world','nuka world traders, coerced park merchants, nuka town market, raider controlled trade, collared trader community','organization','nuka_world_traders','83efcbcf618325c3cc0f854ecd7f3383a52dec17e70f10fdf99db91cdb147943'),
('nuka_world_operators','Operators gang','The Operators are one of Nuka-World''s raider gangs, known for placing profit and accumulated caps at the center of their ambitions. Their base is the Parlor, a former dinner theater in Nuka-Town USA. Mags Black, William Black and Lizzie Wyath are publicly associated with the group. The gang''s organized, composed image coexists with armed raiding and coercion. Knowing its public priorities does not reveal private family histories, experimental chemicals or plans for a particular target.','nuka_world_lore,operators_lore','The Operators are a Nuka-World raider gang associated with the Parlor. Their public priorities emphasize money, organized business and making the park profitable for themselves.','nuka_world','operators raider gang, profit seeking raiders, parlor headquarters, nuka world factions, formal raider attire','organization','nuka_world_operators','61655afcc64752bcf1f322dea46f9f6049b7cab5a300ab8ad4b363578aeb95e2'),
('nuka_world_disciples','Disciples gang','The Disciples are a Nuka-World raider gang with a public reputation for cruelty and enjoyment of violence. Their group is associated with Fizztop Mountain, and Nisha, Dixie and Savoy are recognizable leading members. Distinctive masks, metal armor and bladed styling fit the gang''s threatening image, though members also use firearms. Their reputation describes the group rather than revealing an individual''s past, private correspondence or intentions in a particular encounter.','nuka_world_lore,disciples_lore','The Disciples are a Nuka-World raider gang known for cruelty and violence. They are associated with Fizztop Mountain and distinctive masked, bladed-looking equipment.','nuka_world','disciples raider gang, masked park raiders, fizztop mountain headquarters, nuka world factions, violent gang reputation','organization','nuka_world_disciples','b1a20c61694ec10b36dc4b6f78aef713d15957c0638adb636b3b4121907f7a81'),
('nuka_world_pack','The Pack gang,Pack raiders','The Pack is a Nuka-World raider gang associated with the Bradberton Amphitheater. Its members follow an animal-inspired hierarchy and display bright clothing, animal masks and decorated armor. Mason is a public leading figure, and the gang is known for keeping wasteland animals and valuing demonstrations of strength. Members use painted melee weapons as well as firearms. The group''s imagery and customs do not establish control over a particular creature or guarantee a visitor''s safety.','nuka_world_lore,pack_lore','The Pack is a Nuka-World raider gang with animal masks, bright equipment and a hierarchy based on strength. Its camp is associated with the Bradberton Amphitheater.','nuka_world','pack raider gang, animal themed raiders, bradberton amphitheater camp, nuka world factions, strength based hierarchy','organization','nuka_world_pack','fcab1d94c9f42d17cfc73a6e0a0bbc4df6b97fc9cb2d259ba0858b4a432fbd33'),
('galactic_zone','Nuka-World Galactic Zone','The Galactic Zone is Nuka-World''s space-themed attraction area, opened before the Great War through cooperation among Nuka-Cola, RobCo, Vault-Tec and other companies. Its attractions include Nuka-Galaxy, RobCo Battlezone, Starport Nuka and Vault-Tec: Among the Stars. The setting uses futuristic displays and robots to sell an imagined space age. In the post-war park, surviving automated equipment can be dangerous. Recognizing the attraction gives no knowledge of its control-system condition or restricted operating procedures.','nuka_world_lore,nuka_world_technology','The Galactic Zone is Nuka-World''s space-themed park area. Futuristic attractions and surviving robots reflect its pre-war collaboration with RobCo, Vault-Tec and other companies.','nuka_world','galactic zone attractions, space themed amusement park, robotic park security, prewar corporate collaboration, futuristic tourist displays','location','galactic_zone','76181a57019f45460a7a4799e376b8e66f88770c14979d3f4f8cc49001b166e9'),
('dry_rock_gulch','Nuka-World Wild West park','Dry Rock Gulch is Nuka-World''s Wild West-themed area, built as the park''s first expansion. Its Main Street includes a saloon and blacksmith setting, with a theater, mock ranch and minecart coaster elsewhere in the zone. Named Protectrons perform cowboy and sheriff roles, continuing the old attraction''s routines. Bloodworms and other hostile insects have made the ruins dangerous. The old frontier show should not be confused with a functioning present-day town or reliable local law enforcement.','nuka_world_lore','Dry Rock Gulch is Nuka-World''s Wild West attraction, with a saloon, cowboy robots and a minecart coaster. The ruined area is known for dangerous insects.','nuka_world','dry rock gulch, wild west attractions, cowboy protectron performers, minecart coaster ruins, dangerous park insects','location','dry_rock_gulch','d4208db309a189dac59539362ee59d75cdee201e0c925738066e2cd3490ae3da'),
('safari_adventure','Nuka-World safari park','Safari Adventure is Nuka-World''s wildlife-themed attraction. Its public features include animal enclosures, primate and reptile houses, the Welcome Center, Jungle Journey Theater and Cappy''s treehouse. The area is associated with dangerous gatorclaws and other surviving animals, making exploration hazardous. A river and several paths run through the enclosed grounds. Familiarity with the attraction or its visible wildlife gives no knowledge of restricted scientific facilities, the origin of its creatures or the fate of its inhabitants.','nuka_world_lore,nuka_world_ecology','Safari Adventure is Nuka-World''s animal-themed amusement park area. Old enclosures, animal houses and a treehouse survive among dangerous wildlife, including gatorclaws.','nuka_world','safari adventure attractions, animal themed amusement park, dangerous gatorclaw wildlife, old animal enclosures, jungle journey theater','location','safari_adventure','b4de0b2ea2162c405570fdb69b02dda334ff5a38547ea23a18a21a6b87c804d8'),
('kiddie_kingdom','Nuka-World children''s park','Kiddie Kingdom was designed for Nuka-World''s younger visitors, using clowns, candy-shaped buildings and gentler rides. King Cola''s Castle, the Fun House, Ferris Wheel and smaller attractions remain landmarks in the enclosed area. Its post-war reputation includes feral ghouls and radioactive mist, making the cheerful appearance misleading for travelers. Present hazards must be assessed locally. The public theme and visible defenses provide no knowledge of employees'' private history, missing people or later events in the park.','nuka_world_lore','Kiddie Kingdom is Nuka-World''s candy-and-clown-themed children''s area. Its cheerful ruins include a castle and Fun House, but it is known for radiation and feral ghoul danger.','nuka_world','kiddie kingdom attractions, children amusement area, king cola castle, radioactive park mist, feral ghoul danger','location','kiddie_kingdom','e50d96ebdaf3ee875b56023cc54b9d4995480a02eaf2e208f795e0cc73267141'),
('world_of_refreshment','Nuka-Cola factory tour','The World of Refreshment is a Nuka-World attraction attached to the Nuka-Cola bottling plant. Its boat-tour route followed a Quantum-themed river past displays promoting the company''s history. The ruined interior contains damaged tour equipment, factory machinery and surviving robotic security. The old visitor experience and production areas share the same industrial complex. A public factory tour does not grant knowledge of locked employee systems, protected beverage research or military projects.','nuka_world_lore,nuka_world_technology','The World of Refreshment is Nuka-World''s old Nuka-Cola factory tour. A themed river and company-history displays run through damaged attractions beside bottling equipment.','nuka_world','world of refreshment, nuka cola factory tour, quantum river attraction, bottling plant machinery, robotic factory security','location','world_of_refreshment','331cf5176ccfc8c1a52c3d1e40be5c578eee1b1334644664b37b30a1c19afd2f'),
('nuka_express','Nuka-Express monorail,Nuka-World monorail','The Nuka-Express is the monorail linking the Nuka-World transit center near Boston with the park''s Nuka-station. Before the Great War, it moved visitors and employees along a regular schedule. The elevated line approaches the park through a rocky tunnel and ends at the station. Emergency power has kept the system capable of operation after the main park grid failed. Actual service, destination safety and access to the controls depend on the present condition of the route.','nuka_world_lore,nuka_world_navigation','The Nuka-Express is the monorail between the Boston-area transit center and Nuka-World''s station. Its elevated route was built to carry park visitors and employees.','nuka_world','nuka express monorail, park transit infrastructure, boston transit center, elevated rail route, prewar visitor transportation','technology','nuka_express','cc9a911f0f13636fd7375c985dc448b7e3988bf4d62d204c50f01084229e8647'),
('mechanist_fiction','comic Mechanist,Silver Shroud Mechanist','The Mechanist is a fictional villain in the pre-war Silver Shroud entertainment franchise. Stories set this armored, robot-commanding antagonist against the Silver Shroud and the Mistress of Mystery. Radio plays and Hubris Comics material preserve the persona as part of Boston''s old popular culture. A costume, name or robot-themed speech can recall the character without proving that its wearer is any real person from the stories. Fictional recognition supplies no identity or biography for a post-war imitator.','comic_lore,prewar_culture','The Mechanist is a robot-commanding fictional villain from pre-war Silver Shroud stories. The persona appears in entertainment and can be recognized as a costume or cultural reference.','prewar,comic_observed','fictional mechanist villain, silver shroud entertainment, prewar comic culture, robot commanding antagonist, hubris comics franchise','concept','mechanist_fiction','28928c1ed4783ca0327a75f49a63ae1f3d4fdd397a196859f8a00e312cf8e602'),
('robot_workbench','robot assembly bench,Automatron workbench','A robot workbench is a large assembly station for constructing and modifying compatible robots. Its fittings can support combinations of heads, torsos, arms, legs and other parts from familiar robot designs, including arrangements never sold by the original manufacturers. Voice and paint changes are possible for suitable units. The station needs materials, appropriate components and technical knowledge; owning the equipment does not imply every part is available or that an individual robot has consented to a change.','robot_workbench_knowledge','A robot workbench is a large station for assembling and modifying compatible robots. Its supports and tools allow trained users to fit different robot components.','automatron_observed','robot assembly stations, compatible robot components, automatron workshop equipment, robotic modifications, technical assembly work','technology','robot_workbench','7db27cb8f93f379f2d91735270162b6bc18da69951d754db7a339a74d126bddf'),
('rust_devils','Rust Devil gang','The Rust Devils are raiders associated with robots and equipment made from salvaged robotic parts. Members wear robot armor and may travel with modified machines, combining human gunfire with mechanical threats. They have been encountered around the Commonwealth fighting other groups and threatening settlements. Their distinctive gear can help an experienced traveler recognize the gang, but does not reveal a machine''s present programming, a raider''s private plans or who currently holds a particular industrial site.','automatron_lore','The Rust Devils are a raider gang known for robot-based equipment and mechanical companions. Their salvaged robot armor makes them distinctive when encountered.','automatron_observed','rust devils raiders, salvaged robot armor, modified mechanical companions, automatron encounter knowledge, robot themed gang','organization','rust_devils','98d0a87c87b89037999ca71824729360dea17bbe286ebacbcbb0ddea3c990805'),
('robobrain','Robo-brain,Robobrains','Robobrains are tracked robots whose central processor is an organic brain enclosed in a protective dome. General Atomics developed the design with military involvement and indirect RobCo support for civilian and military roles. Flexible arms let them manipulate equipment, while a robust chassis carries their power and control systems. Surviving examples can have specialized weapons and unreliable behavior. Recognition of the design gives no knowledge of whose brain a unit contains, its memories or its current orders.','robotics,military_robotics','Robobrains are tracked robots with an organic brain in a protective dome. Their unusual processor and mechanical body distinguish them from ordinary circuit-controlled robots.','robobrain_observed,automatron_observed','organic brain robots, tracked robot chassis, robobrain mechanical design, military robot development, general atomics engineering','robot','robobrain','94f9e7b161415c6343fe80ae7b54b8f02ad37aa6633c676a0825f0e358754125'),
('sentry_bot','Sentry bots,military sentry robot','Sentry bots are heavy military security robots built for overwhelming firepower. The Commonwealth design has a broad armored torso, wheeled supports and heavy weapon mounts; units can carry miniguns, missiles or other powerful armaments. Sustained activity can produce an overheating cooldown, and a destroyed unit may erupt in a dangerous explosion. Their strength makes caution appropriate, but a machine''s actual weapons, activation state and allegiance follow inspection and present programming rather than model recognition.','robotics,military_robotics','Sentry bots are large armored combat robots carrying heavy weapons. Their speed and firepower make them dangerous, and a destroyed unit can still explode.','prewar,commonwealth','heavy military robots, armored sentry design, robot security weapons, overheating combat machines, explosive robot wrecks','robot','sentry_bot','4afb07602185a86f6e311aa5c4ecd5e59a50b1543bdf49352b50af9d6e1b7898'),
('eyebot','Eyebots,floating broadcast robot','Eyebots are small floating robots with a spherical body, antennae and a prominent loudspeaker. Around the Commonwealth, they may broadcast radio, old advertisements or static while moving through settlements and ruins. A small laser gives many units a limited defensive capability. Their size and broadcasting role distinguish them from heavier service or combat robots. An individual broadcast does not prove who owns the unit, whether its message is current or what instructions the robot presently follows.','robotics','Eyebots are small floating robots with antennae and loudspeakers. Broadcasting radio messages and advertisements is one of their familiar uses in public spaces.','prewar,commonwealth','floating broadcast robots, robotic loudspeakers, prewar radio advertising, small laser defense, commonwealth robot encounters','robot','eyebot','42980162f2db3ff60a1dc18a68db5b40334b9a0bb09bd88ecd8eaced1eb84ec7'),
('vault_88','Vault Eighty-Eight','Vault 88 is an unfinished Vault-Tec shelter beneath Quincy Quarries. Construction stopped when the Great War interrupted the project, leaving completed entrance, security and reactor areas beside much larger unfinished caverns. Construction machinery, rail equipment and debris show how much work remained. The space can support further shelter construction by people who have gained legitimate access and the means to work there. Its current residents, completed rooms and safety depend on observed conditions, while restricted records remain separate knowledge.','vault88_lore','Vault 88 is an unfinished underground Vault-Tec shelter beneath Quincy Quarries. Completed entrance rooms lead toward large caverns where construction stopped at the Great War.','vault88_observed','unfinished vault shelter, quincy quarry construction, vault 88 caverns, interrupted prewar building, underground construction machinery','location','vault_88','5dd4c9eda12931e03e03bc687c2798b580971067ccde88299f8870583a822187'),
('modular_vault_construction','Vault room modules,Vault-Tec prefabs','Vault-Tec construction uses prefabricated room and corridor sections that fit together into larger shelters. Familiar module types include domestic and utility halls, atrium pieces, stairs, doors, railings and specialized rooms for quarters, security, clinics and the overseer. Components provide a planned alternative to improvised surface shacks. A recognizable module does not establish that a shelter is complete, structurally sound or operating as advertised; those conditions require inspection and maintenance.','vault_construction_knowledge,vault88_lore','Vault construction can use fitted prefabricated halls, rooms, atrium sections and supports. Recognizable modular pieces help builders arrange underground living and service areas.','vault88_observed,vault_construction_observed','modular vault rooms, prefabricated underground halls, vault construction supports, atrium building components, shelter maintenance work','technology','modular_vault_construction','34fef9bdc15d8d2a5b5d22449609a20dbb03d7b01b2315c320f1bfb2431cd469'),
('contraptions_manufacturing','manufacturing machines,Contraptions workshop builder','Settlement manufacturing equipment can turn supplied components into finished goods using powered machines. A builder produces familiar objects such as toys, sporting items and lunchboxes from materials placed in its own inventory. A connected terminal selects production settings, and conveyor equipment can handle input or output. Other machines specialize in clothing, armor, food or weapons. Resources and compatible machinery limit production; a functioning-looking line does not establish that supplies or finished goods are available.','contraptions_knowledge','Powered manufacturing machines can turn supplied components into goods. Builders and specialized equipment need materials, suitable settings and someone who knows the production system.','contraptions_observed','powered manufacturing machines, component based production, terminal production settings, settlement industrial equipment, conveyor material handling','technology','contraptions_manufacturing','4f66b3efa505d168a8e67a5f40e47ff0fb843626428bb6bc91375508c950fe65'),
('conveyor_belts','conveyor belt,belt splitter','Conveyor belts move objects between compatible manufacturing and handling equipment. Straight sections of different lengths and splitters allow an industrial line to distribute items along more than one path. In the settlement machinery system, belts work through a connected powered machine rather than being wired directly to a generator, and longer runs need appropriate additional power connections. Actual movement depends on working equipment and the objects placed on it; the belt itself does not manufacture or identify items.','contraptions_knowledge','Conveyor belts carry objects along manufacturing lines. Different lengths and splitters connect compatible machinery, while power and working connections keep the line moving.','contraptions_observed','industrial conveyor belts, manufacturing material transport, belt splitter equipment, connected powered machinery, settlement production lines','technology','conveyor_belts','096bcb6f5887b77389a0cfc15210a557d94fa6b62291d103c18ba3aafdfc4071'),
('decontamination_arch','radiation arch,decontamination equipment','A decontamination arch is powered equipment intended to remove accumulated radiation from someone passing through it. The settlement version has an integrated switch and requires connection to a generator. Its presence may be useful to people working around contaminated areas, but it must actually be powered and operating to provide treatment. Recognition alone does not establish how another arch has been configured, whether a person has used it or whether an individual radiation problem has been resolved.','wasteland_workshop_knowledge','A decontamination arch is powered equipment for reducing radiation exposure when someone passes through it. Its generator connection and working condition matter.','wasteland_workshop_observed','powered decontamination equipment, radiation removal arch, settlement treatment machinery, generator powered arch, equipment working condition','technology','decontamination_arch','43a7478f8a21d1b922e5c439a76187f550ac1e24d96f706f8bdbe881fdf4e912'),
('wasteland_capture_cages','capture cages,animal traps','Powered capture cages are specialized enclosures designed for particular animals or hostile creatures. Their sizes and bait suit different targets, from small animals to large wasteland predators. After capturing and releasing a target, a cage needs repair before another use. Captivity does not make every creature tame: many remain dangerous when released, and keeping them can attract further trouble to a settlement. A closed cage or noise gives evidence to inspect rather than certainty about the exact creature inside.','wasteland_workshop_knowledge','Capture cages are powered traps built for particular animals or creatures. A captured predator may remain dangerous, and cages need repair after use.','wasteland_workshop_observed','powered capture cages, specialized animal traps, dangerous captive predators, settlement cage maintenance, creature release hazards','technology','wasteland_capture_cages','009db70b4f46d1959af19cf3484c361ca18fe974b66d8d09c4cbeccaac96df6b'),
('wasteland_vocabulary','wasteland terms,postwar vocabulary','Everyday wasteland language reflects local food, trade, medicine and survival. A tato is a crop combining tomato and potato traits. Caps are bottle caps used as currency. Chems include medicines and performance drugs with different effects; addictive chems can cause dependence. Rads refer to radiation, while Rad-X and RadAway serve different purposes. Prewar consumer brands and old American entertainment remain recognizable parts of public life.','commonwealth_lore','Tatos are familiar wasteland food crops combining tomato and potato traits; they are not simply ordinary tomatoes. Mutfruit is a cultivated fruit, and razorgrain is a grain crop. Caps means bottle caps used as money, alongside barter. Chems are medicines or drugs: Jet changes the user''s perception of time, Psycho aids combat, Buffout boosts physical performance, Mentats sharpen mental faculties, and Med-X relieves pain. Some chems are addictive. Stimpaks treat injuries, RadAway removes accumulated radiation, and Rad-X temporarily improves radiation resistance. Rads means radiation exposure. Nuka-Cola, canned Cram and Sugar Bombs are recognizable consumer brands. Old radio songs, diners, cheerful advertising, domestic robots and atomic technology belong to familiar American culture. Speech ranges from formal to rough or old-fashioned; those surroundings do not give everyone the same slang.','common','wasteland vocabulary, everyday terminology, postwar public knowledge, familiar consumer culture','concept','wasteland_vocabulary','f0df2c7189d6fae014de996bd7354f85b0ee5ce282aa7a9fa8d1ea2ef5c26a48'),
('tato','tatos,tatoes','Tatos are hardy food crops with tomato-like skin and potato-like flesh. Botanical notes describe the plant as a hybrid associated with the old tomato and potato. The red appearance does not make a tato an ordinary tomato. Farmers cultivate tatos for food and trade, and the crop also appears in cooking and vegetable-starch production. Taste and crop quality can vary.','farmer,agriculture','A tato is a familiar red-skinned wasteland food crop combining tomato and potato traits. Tatos are grown on farms and used for food and trade.','common','tato crop, hybrid food plant, tomato potato traits, wasteland produce','flora','tato','13eb21304a43209fe88055f3513018f08aa595b393ff03dee9c01ebc1e9a69d8'),
('mutfruit','mutfruits','Mutfruit grows on small trees and is cultivated as a food crop. Farmers value its sweet fruit for eating, cooking and sale. Harvested fruit can supply planting stock, while wild mutfruit is a distinct gathered ingredient. Corn, tatos and mutfruit can contribute to vegetable starch when combined with water. Familiarity with the crop does not imply knowledge of a particular farm''s stock or experimental strains.','farmer,agriculture','Mutfruit is a sweet fruit grown on small trees and familiar on wasteland farms. Cultivated mutfruit and wild mutfruit are distinct ingredients used for food.','common','mutfruit cultivation, sweet tree fruit, cultivated fruit, wild crop distinction','flora','mutfruit','403bd8c1877e3efa1558313d73b138454dadf8972a41cec3c130fe03b9ad75b8'),
('razorgrain','razorgrains','Razorgrain is a cultivated grain with an edible harvest. Botanical notes discuss its use as a possible substitute where wheat is difficult to grow, while also noting unreliable yields. Grinding and cooking make it useful in food preparation. It appears in dishes such as noodle cups and mirelurk cakes. The crop''s name does not make every old wheat product razorgrain.','farmer,agriculture','Razorgrain is a familiar wasteland grain crop grown for food. Its harvested grain is used in cooking, including noodle cups and other prepared dishes.','common','razorgrain harvest, edible grain crop, grain food preparation, cultivated cereal plant','flora','razorgrain','c424a52f9c5a7883032f487fa09563429bd15b63c8c2f205f3d48c63442f8054'),
('tarberry','tarberries','Tarberries are small purple berries associated with water-growing plants. They can be cultivated in shallow water, including adapted pools, rather than ordinary dry crop rows. The berries are eaten and used in food preparation and some chem recipes. Their usefulness makes them a trade crop. Knowing tarberries does not establish knowledge of a particular grower''s location, harvest or trading arrangements.','farmer,agriculture','Tarberries are small purple berries grown in water and used for food and trade. They are a familiar crop with different growing needs from dry-field plants.','common','tarberry cultivation, water grown berries, purple food berries, aquatic crop harvest','flora','tarberry','6fccf0809d918b3647e4a37781c77377ad3b0af544158a0616984ef75247a549'),
('wasteland_cooking','wasteland meals,cooked wasteland food','Wasteland cooks make meals from harvested crops and local meat using fires, pots, stoves and cooking stations. Familiar dishes include grilled radstag, roasted mirelurk meat and vegetable soup. Many prepared dishes have different effects and radiation levels from their raw ingredients. Preparing a meal does not establish that a particular kitchen has supplies or that any named person has already eaten. Local recipes and available ingredients vary.','farmer,agriculture','Wasteland meals use crops and local meat, prepared over fires or at cooking stations. Grilled radstag, roasted mirelurk and vegetable dishes are familiar prepared foods.','common','wasteland food preparation, cooked local meat, crop based meals, cooking station dishes','food_drink','wasteland_cooking','c0b8373b3e9af32982f401dd7a38d41e7ee7da241e7f55270b9c4c038b6c6929'),
('prewar_packaged_food','Cram,can of Cram,Sugar Bombs,Blamco Brand Mac and Cheese,Fancy Lads Snack Cakes,InstaMash','Familiar packaged-food brands include Cram canned meat, Sugar Bombs breakfast cereal, Blamco macaroni and cheese, Fancy Lads snack cakes and InstaMash. Wasteland supplies include both preserved and irradiated examples. A recognizable brand does not prove that a particular package is safe or centuries old: some food can also be manufactured using surviving equipment. Traders distinguish the actual product and its condition rather than treating every box as identical.','trader,caravan_trade','Cram is canned meat, Sugar Bombs is breakfast cereal, Blamco makes macaroni and cheese, Fancy Lads makes snack cakes, and InstaMash is a packaged potato food.','common,prewar','packaged food brands, canned meat products, branded breakfast cereal, preserved food supplies','food_drink','prewar_packaged_food','4a4bdd14cc16ff5f769a09c90a4e16ca51aa56858ecb182b0b7802bde3f76569'),
('bottle_caps','caps,bottlecap,bottlecaps','Bottle caps are a widely accepted wasteland currency, especially recognizable Nuka-Cola caps. Commonwealth merchants use them for goods and services, while barter remains possible. Caps are money because people accept them in exchange; their value in a particular deal depends on the goods and the bargain. The Commonwealth''s use of caps does not establish that its currency shares the Hub''s western water-backing system or a fixed exchange rate with old dollars.','trader,caravan_trade','Caps are bottle caps used as money by wasteland traders. They pay for goods and services, while people also barter items and negotiate individual deals.','common','bottle cap currency, wasteland money, cap based trade, merchant barter payments','item','bottle_caps','01a87892c1782cc6aba8214e2487ab938e71f4593ab5d2683707beaed560ff7a'),
('chems','chem,chemical drugs','Chems include injury treatments, radiation medicines and drugs used for mental or physical performance. Stimpaks, RadAway and Rad-X serve different medical purposes; Jet, Psycho, Buffout, Mentats and Med-X have their own temporary effects. Many performance chems can cause addiction, but that does not mean every medicine is addictive. A brand name alone does not establish someone''s current condition, dependence, supplies or consent to treatment.','medicine,doctor','Chems are medicines or drugs used in the wasteland. Their effects differ, and some are addictive; injury treatment, radiation medicine and performance drugs are distinct uses.','common','wasteland chem terminology, fictional medical products, performance drug effects, chem addiction recognition','medicine','chems','7f722f82928bf53d279539d19aefb1c9db660d2573fcaed4bd34506bd761186f'),
('jet','Jet inhaler','Jet is commonly recognizable as a small inhaler chem. It alters consciousness so that the user experiences time as slowing for a short period. This is an effect on the user''s perception and performance, rather than proof that the whole world stops. Jet can cause addiction.','medicine,doctor','Jet is an addictive inhaler chem that briefly changes the user''s perception of time, making events seem slower. It is familiar as a wasteland performance drug.','common','jet inhaler chem, altered time perception, addictive performance drug, temporary consciousness effect','medicine','jet','db2a13e8c9ccb9545b6e2b59ef494ee5a3b7c07b105cd98870c76e50024c38da'),
('psycho','Psycho chem','Psycho was developed for military combat performance before the Great War. It is recognizable as an injected chem and temporarily increases combat effectiveness and resistance to harm. Psycho can cause addiction. Mixed products bearing its name have their own effects and should not all be treated as the same substance. Its reputation does not establish that a particular person is using it or is inevitably violent.','medicine,doctor,soldier','Psycho is an injectable combat chem used to temporarily improve fighting performance and resistance to harm. It can cause addiction and is distinct from ordinary injury treatment.','common,prewar','psycho combat chem, military performance drug, injectable chem recognition, combat chem addiction','medicine','psycho','7c42b344aae256393ffa936ac361a6301dfe1805768d263f8a3d570d7e8dbd9b'),
('buffout','Buffout chem','Buffout is a steroid chem associated with physical performance and was popular with athletes before the Great War. It temporarily improves strength, endurance and resilience. It is commonly found in a small jar rather than being the same product as an inhaler or injectable chem. Buffout can cause addiction, and its combined variants should not automatically be assigned every effect of the original product.','medicine,doctor','Buffout is a steroid chem used to temporarily improve strength, endurance and physical resilience. It can cause addiction and is recognizable as a performance-enhancing product.','common,prewar','buffout steroid chem, athletic performance product, temporary physical enhancement, physical chem addiction','medicine','buffout','bb37722192c232dff141872a5a94322907e3f507e8aa962a56191c452c5503d1'),
('mentats','Mentat,Mentats chem','Mentats are a branded chem associated with temporary improvements in perception and intellectual performance. Their recognizable tin contains tablets. Mentats can cause addiction, so their reputation as a mental aid does not make them harmless. Flavored or altered varieties have different specialties, including Berry, Grape and Orange Mentats; knowledge of the ordinary product does not establish the effects of every variant.','medicine,doctor','Mentats are a tablet chem used to temporarily sharpen perception and mental performance. They can cause addiction and are recognizable by their branded tin packaging.','common,prewar','mentats mental aid, tablet chem recognition, temporary perception enhancement, mental chem addiction','medicine','mentats','0c63563a808659b14b68224a75c34fa4efebb8ea4a3208130072434cb2e1b355'),
('med_x','MedX','Med-X is an injectable painkiller. Its effect includes temporarily improving resistance to harm, but pain relief and resistance are different from repairing an injury with a stimpak. Med-X can cause addiction. The syringe''s presence alone does not establish that a person has used it or that an injury has healed. Recognizing the product is distinct from having the medical skill or supplies to treat someone.','medicine,doctor','Med-X is an injectable painkiller that temporarily improves resistance to harm. It can cause addiction, and its pain relief differs from repairing injuries with a stimpak.','common,prewar','med x painkiller, injectable pain medicine, temporary damage resistance, pain relief distinction','medicine','med_x','6b4836f7e99e2686895fe78266b88e536774510e9a6178dd860276022779fb88'),
('rad_x','RadX','Rad-X temporarily increases resistance to radiation. It is intended to reduce the impact of exposure and is distinct from RadAway, which removes radiation already accumulated in the body. Rad-X is commonly recognizable as pills in a medicine bottle. Protection is limited and does not make someone immune to radiation or prove that a contaminated area is safe. Its use does not establish that existing exposure has been removed.','medicine,doctor','Rad-X is a radiation-protection medicine that temporarily improves resistance to exposure. It differs from RadAway, which removes accumulated radiation, and does not provide complete immunity.','common,prewar','rad x protection, temporary radiation resistance, radiation medicine distinction, exposure prevention medicine','medicine','rad_x','7d8d8cc5b7e604becb82991992203f6bc427efbb4a28027225575bcedb7dbfd2'),
('addictol','Addictol inhaler','Addictol is a medicine used to remove chem dependence and alcohol addiction. Its small inhaler can resemble Jet, although the products have different purposes. Removing an existing addiction is distinct from preventing future dependence after more use. Recognition of Addictol does not establish that it is available, that treatment has happened, or that a particular person''s complicated medical history has been resolved.','medicine,doctor','Addictol is a medicine used to treat chem addiction. It is supplied as an inhaler; recognizing the product does not establish a current addiction, treatment or available stock.','common','addictol addiction medicine, dependence treatment product, addiction recovery aid, inhaler product distinction','medicine','addictol','ccad162316c601a2de6573f5839b554f1978bfad7b11c5693d27df919ba727cb'),
('prewar_american_culture','old American culture,prewar popular culture,American consumer culture','Prewar American public life featured branded convenience foods, soda advertising, radio entertainment, roadside diners, comic heroes and domestic robots. Atomic technology could appear beside familiar household furnishings and cheerful commercial imagery. These surroundings help explain recognizable old consumer culture without establishing that every person speaks in slogans or shares the same opinions. Regional customs, profession, upbringing and individual temperament shape how people actually talk.','prewar_culture','American consumer culture includes radio songs, roadside diners, soda brands, cheerful advertisements, comic heroes, domestic robots and atomic technology. Individual people still have their own manners and speech.','common,prewar','american consumer culture, atomic household technology, radio entertainment traditions, retro commercial imagery','culture','prewar_american_culture','ac29a1b40f96c078e8c1d58f02b42055089b87fa1cc0f24d3233e7d8deab12da'),
('smoothskin','smoothskins,smooth-skin','Some ghouls use smoothskin for a human who is not a ghoul, referring to the visible difference in skin. The term can appear in ordinary conversation, teasing or hostility, depending on the speaker and situation. It does not by itself show contempt, and it does not describe a person''s intelligence or moral character. Other speakers may simply say human or use a person''s name.','commonwealth_lore','Smoothskin is a term some ghouls use for a human who is not a ghoul. Its tone depends on the speaker and situation, rather than one fixed meaning.','common','smoothskin colloquial term, ghoul human vocabulary, contextual speech register, visible skin distinction','culture','smoothskin','8f9d987bf3997de97a62c26cb5a8764463a403016144cbd57f5bcdb7c3e58feb'),
('prewar_money','old dollars,prewar cash','Prewar money consists of old United States banknotes. In ordinary Commonwealth trade, caps have replaced dollars as the expected payment, although old cash can still be exchanged or salvaged for cloth. That usefulness means the notes are not automatically worthless. Specialized machines or unusual arrangements may differ from ordinary trade, but recognizing a banknote does not establish knowledge of every regional payment system.','trader,caravan_trade','United States paper banknotes are dollar-denominated cash. Printed denominations identify the amount each bill represents, and the notes belong to American paper-currency traditions.','common,prewar','united states banknotes, old paper currency, salvaged cash material, dollar cap distinction','item','prewar_money','1b65e4da929e56bf04fb80cb3624602efd7644d21a95bc62e1a22ebc640d3a2b'),
('noodle_cup','noodle cups,cup of noodles','Noodle cups are a familiar prepared food made with razorgrain and water. In Diamond City, Takahashi sells them at Power Noodles, making the dish recognizable in the public marketplace. Takahashi is not the only possible source of noodle cups; other food sellers and cooks can provide them. Knowing the dish does not establish any vendor''s present stock, prices or a conversation in a language the vendor does not speak.','commonwealth_lore','A noodle cup is a familiar prepared wasteland dish made with razorgrain and water. Cooks and food vendors provide it as a meal.','common','razorgrain noodle dish, prepared noodle cup, familiar vendor food, grain based meal','food_drink','noodle_cup','a7d90d02321ff4b7fbd7b6d7b7a2d1e20db831fe2b060c0ba35e2f4323f2d451')) AS seed(topic,aliases,topic_desc,knowledge_class,topic_desc_basic,knowledge_class_basic,tags,category,canonical_topic,content_hash)
ON CONFLICT (catalog_id,catalog_version,canonical_topic) WHERE source_kind='factory' DO UPDATE SET
topic=EXCLUDED.topic,
aliases=EXCLUDED.aliases,
topic_desc=EXCLUDED.topic_desc,
knowledge_class=EXCLUDED.knowledge_class,
topic_desc_basic=EXCLUDED.topic_desc_basic,
knowledge_class_basic=EXCLUDED.knowledge_class_basic,
tags=EXCLUDED.tags,
category=EXCLUDED.category,
content_hash=EXCLUDED.content_hash,
native_vector=EXCLUDED.native_vector,
updated_at=CURRENT_TIMESTAMP
WHERE (worldknowledge.topic,worldknowledge.aliases,worldknowledge.topic_desc,worldknowledge.knowledge_class,worldknowledge.topic_desc_basic,worldknowledge.knowledge_class_basic,worldknowledge.tags,worldknowledge.category,worldknowledge.content_hash,worldknowledge.native_vector) IS DISTINCT FROM (EXCLUDED.topic,EXCLUDED.aliases,EXCLUDED.topic_desc,EXCLUDED.knowledge_class,EXCLUDED.topic_desc_basic,EXCLUDED.knowledge_class_basic,EXCLUDED.tags,EXCLUDED.category,EXCLUDED.content_hash,EXCLUDED.native_vector);

-- Retain unrelated catalogue rows and any explicit foreign active selection.
DO $catalogue_activation$
BEGIN
IF NOT EXISTS (SELECT 1 FROM synth.worldknowledge_catalogs WHERE is_active AND catalog_id<>'fallout-4-starter-official') THEN
  UPDATE synth.worldknowledge_catalogs SET is_active=FALSE
    WHERE is_active AND catalog_id='fallout-4-starter-official' AND catalog_version<>'content-v4-2026-10-08';
  UPDATE synth.worldknowledge_catalogs SET is_active=TRUE,activated_at=COALESCE(activated_at,CURRENT_TIMESTAMP)
    WHERE NOT is_active AND catalog_id='fallout-4-starter-official' AND catalog_version='content-v4-2026-10-08';
END IF;
END;
$catalogue_activation$;
